import json, os, subprocess, tempfile, shutil
EXE='/workspace/executable'
ENV=dict(os.environ, RAYON_NUM_THREADS='4')
def run_batch(files, exe=EXE, extra=(), keep=False):
    """files: list of (relpath, content(bytes or str)). returns dict relpath->(lang, stats)"""
    d=tempfile.mkdtemp(prefix='tkp', dir='/tmp/work')
    try:
        for p,c in files:
            fp=os.path.join(d,p)
            dn=os.path.dirname(fp)
            if not os.path.isdir(dn): os.makedirs(dn,exist_ok=True)
            if isinstance(c,str): c=c.encode()
            with open(fp,'wb') as f: f.write(c)
        out=subprocess.run([exe,'-o','json','--hidden','--no-ignore',*extra,'.'],cwd=d,capture_output=True,env=ENV)
        j=json.loads(out.stdout)
        res={}
