import json
P=json.load(open('/tmp/db/tokprobe.json'))
langs=[n for n,_ in json.load(open('/tmp/langlist.json'))]
def cat(r):
    if r is None: return 'NONE'
    c,m,b,bl=r
    if bl: return 'CTX'+str((c,m,b))
    if (c,m,b)==(1,1,1): return 'LC'
    if (c,m,b)==(0,3,0): return 'ML'
