# Python model of tokei counting (no contexts)
WS=b' \t\n\r\x0b\x0c'
def trim(b): return b.strip(WS)
class Lang:
    def __init__(self, lc=(), ml=(), nested=False, nc=(), q=(), vq=(), dq=(), literate=False, fortran=False, important=()):
        self.lc=[x.encode() for x in lc]
        self.ml=[(a.encode(),b.encode()) for a,b in ml]
        self.nested=nested
        self.nc=[(a.encode(),b.encode()) for a,b in nc]
        self.q=[(a.encode(),b.encode()) for a,b in q]
        self.vq=[(a.encode(),b.encode()) for a,b in vq]
        self.dq=[(a.encode(),b.encode()) for a,b in dq]
        self.literate=literate
        self.fortran=fortran
        self.important=[s for s,_ in self.q+self.vq+self.dq+self.ml+self.nc]+[x.encode() for x in important]
def lines_iter(text, start=0):
    n=len(text); s=start
    while s<n:
        i=text.find(b'\n',s)
        if i<0: i=n
        yield s,i
        s=i+1
class Counter:
    def __init__(self,L,doc_as_comments=False):
        self.L=L; self.stack=[]; self.quote=None; self.verb=False; self.doc=False; self.dac=doc_as_comments
    def plain(self): return self.quote is None and not self.stack
    def single(self, line, st):
        L=self.L
        if not self.plain(): return False
        if not trim(line): st[2]+=1; return True
        if any(t in line for t in L.important): return False
        if L.literate or any(trim(line).startswith(c) for c in L.lc): st[1]+=1
        else: st[0]+=1
        return True
    def end_quote(self, w):
        if self.quote is not None and w.startswith(self.quote):
            q=self.quote; self.quote=None; return len(q)
        if not self.verb and w.startswith(b'\\\\'): return 2
        if not self.verb and w.startswith(b'\\') and any(w[1:].startswith(s) for s,_ in self.L.q): return 2
        return None
    def end_ml(self, w):
        if self.stack and w.startswith(self.stack[-1]):
            return len(self.stack.pop())
        return None
    def start_quote(self, w):
        if self.stack: return None
        for s,e in self.L.dq:
            if w.startswith(s): self.quote=e; self.verb=False; self.doc=True; return len(s)
        for s,e in self.L.vq:
            if w.startswith(s): self.quote=e; self.verb=True; self.doc=False; return len(s)
        for s,e in self.L.q:
            if w.startswith(s): self.quote=e; self.verb=False; self.doc=False; return len(s)
        return None
    def start_ml(self, w):
        if self.quote is not None: return None
        for s,e in self.L.ml+self.L.nc:
            if w.startswith(s):
                if not self.stack or self.L.nested or (s,e) in self.L.nc:
                    self.stack.append(e)
                return len(s)
        return None
    def line_comment(self, w):
        if self.quote is not None or self.stack: return False
        return any(w.startswith(c) for c in self.L.lc)
    def multi(self, text, start, end):
        skip=0; ended=False
        for i in range(start,end):
            if skip: skip-=1; continue
            w=text[i:]
            if not trim(w): break
            ended=False
            r=self.end_quote(w)
            if r is None: r=self.end_ml(w)
            if r is not None:
                ended=True; skip=r-1; continue
            elif self.quote is not None: continue
            r=self.start_quote(w)
            if r is None: r=self.start_ml(w)
            if r is not None: skip=r-1; continue
            if self.line_comment(w): ended=True; break
        return ended
    def is_comment(self, line, started):
        L=self.L
        t=trim(line)
        if self.quote is not None:
            if self.doc and self.dac: return t.endswith(self.quote)
            return False
        if self.dac and any(t.startswith(s) and t.endswith(e) for s,e in L.dq): return True
        if started: return True
        if any(t.startswith(c) for c in L.lc): return True
        if any(t.startswith(s) and t.endswith(e) for s,e in L.ml): return True
        if self.stack and any(e==self.stack[-1] and t.startswith(s) for s,e in L.ml): return True
        return False
def count(L, text, dac=False):
    if isinstance(text,str): text=text.encode()
    st=[0,0,0]
    c=Counter(L,dac)
    for s,e in lines_iter(text):
        line=text[s:e]
        if not L.fortran: line=trim(line)
        if c.single(line, st): continue
        started = bool(c.stack) or (dac and c.quote is not None and c.doc)
        ended=c.multi(text,s,e)
        if L.literate or c.is_comment(line, started): st[1]+=1
        else: st[0]+=1
    return tuple(st)
