//! Language definitions and lookup helpers.

use crate::langs::LANGS;
use std::path::Path;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Special {
    None,
    Markdown,
    Rust,
    Html,
    LinguaFranca,
    Jupyter,
}

pub struct LangDef {
    pub name: &'static str,
    pub extensions: &'static [&'static str],
    pub filenames: &'static [&'static str],
    pub shebangs: &'static [&'static str],
    pub env: &'static [&'static str],
    pub mime: &'static [&'static str],
    pub line_comments: &'static [&'static str],
    pub multi_line: &'static [(&'static str, &'static str)],
    pub nested: bool,
    pub nested_comments: &'static [(&'static str, &'static str)],
    pub quotes: &'static [(&'static str, &'static str)],
    pub verbatim_quotes: &'static [(&'static str, &'static str)],
    pub doc_quotes: &'static [(&'static str, &'static str)],
    pub important: &'static [&'static str],
    pub literate: bool,
    pub fortran: bool,
    pub special: Special,
}

pub type LangId = usize;

pub fn def(id: LangId) -> &'static LangDef {
    &LANGS[id]
}

pub fn name(id: LangId) -> &'static str {
    LANGS[id].name
}

pub fn count() -> usize {
    LANGS.len()
}

/// Case-insensitive lookup by display name.
pub fn from_name(s: &str) -> Option<LangId> {
    let lower = s.to_lowercase();
    LANGS.iter().position(|l| l.name.to_lowercase() == lower)
}

pub fn from_mime(s: &str) -> Option<LangId> {
    LANGS.iter().position(|l| l.mime.iter().any(|m| *m == s))
}

pub fn from_extension(ext: &str) -> Option<LangId> {
    LANGS.iter().position(|l| l.extensions.iter().any(|e| *e == ext))
}

pub fn from_filename(fname: &str) -> Option<LangId> {
    LANGS.iter().position(|l| l.filenames.iter().any(|e| *e == fname))
}

/// Result of trying to detect the language of a path.
pub enum Detect {
    Found(LangId),
    UnknownExtension(String),
    Unknown,
}

fn rust_ws(c: char) -> bool {
    c.is_whitespace()
}

pub fn from_shebang_bytes(buf: &[u8]) -> Option<LangId> {
    let first = match buf.iter().position(|&b| b == b'\n') {
        Some(i) => &buf[..i],
        None => buf,
    };
    let first = std::str::from_utf8(first).ok()?;
    let mut words = first.split(rust_ws).filter(|w| !w.is_empty());
    let w = words.next()?;
    if w == "#!/usr/bin/env" {
        let word = words.next()?;
        for (i, l) in LANGS.iter().enumerate() {
            if l.env.iter().any(|e| word.starts_with(e)) {
                return Some(i);
            }
        }
        return None;
    }
    LANGS.iter().position(|l| l.shebangs.iter().any(|s| *s == w))
}

pub fn from_shebang(path: &Path) -> Option<LangId> {
    use std::io::Read;
    let mut f = std::fs::File::open(path).ok()?;
    let mut buf = [0u8; 128];
    let mut len = 0;
    // A single read call, mirroring a typical read of up to 128 bytes.
    loop {
        match f.read(&mut buf[len..]) {
            Ok(0) => break,
            Ok(n) => {
                len += n;
                if len >= buf.len() {
                    break;
                }
            }
            Err(_) => return None,
        }
        break;
    }
    from_shebang_bytes(&buf[..len])
}

pub fn detect(path: &Path) -> Detect {
    let fname = path
        .file_name()
        .map(|f| f.to_string_lossy().to_lowercase());
    if let Some(f) = &fname {
        if let Some(id) = from_filename(f) {
            return Detect::Found(id);
        }
    }
    match path.extension() {
        Some(ext) => {
            let ext = ext.to_string_lossy().to_lowercase();
            match from_extension(&ext) {
                Some(id) => Detect::Found(id),
                None => Detect::UnknownExtension(ext),
            }
        }
        None => match from_shebang(path) {
            Some(id) => Detect::Found(id),
            None => Detect::Unknown,
        },
    }
}
EOF
echo ok"}

