//! Statistics containers.

use crate::lang::LangId;
use std::collections::BTreeMap;

#[derive(Default, Clone, Debug, PartialEq, Eq)]
pub struct CodeStats {
    pub blanks: usize,
    pub code: usize,
    pub comments: usize,
    pub blobs: BTreeMap<LangId, CodeStats>,
}

impl CodeStats {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn lines(&self) -> usize {
        self.blanks + self.code + self.comments
    }

    /// Adds another set of stats (including its blobs) to this one.
    pub fn add(&mut self, other: &CodeStats) {
        self.blanks += other.blanks;
        self.code += other.code;
        self.comments += other.comments;
        for (k, v) in &other.blobs {
            self.blobs.entry(*k).or_default().add(v);
        }
    }

    /// Flattens all blobs into a single set of stats.
    pub fn summarise(&self) -> CodeStats {
        let mut s = CodeStats {
            blanks: self.blanks,
            code: self.code,
            comments: self.comments,
            blobs: BTreeMap::new(),
        };
        for v in self.blobs.values() {
            let b = v.summarise();
            s.blanks += b.blanks;
            s.code += b.code;
            s.comments += b.comments;
        }
        s
    }
}

#[derive(Clone, Debug)]
pub struct Report {
    pub name: String,
    pub stats: CodeStats,
}

#[derive(Default, Clone, Debug)]
pub struct Language {
    pub blanks: usize,
    pub code: usize,
    pub comments: usize,
    pub reports: Vec<Report>,
    pub children: BTreeMap<LangId, Vec<Report>>,
    pub inaccurate: bool,
}

impl Language {
    pub fn lines(&self) -> usize {
        self.blanks + self.code + self.comments
    }

    pub fn add_report(&mut self, report: Report) {
        for (lang, stats) in &report.stats.blobs {
            self.children.entry(*lang).or_default().push(Report {
                name: report.name.clone(),
                stats: stats.clone(),
            });
        }
        self.reports.push(report);
    }

    pub fn total(&mut self) {
        let mut b = 0;
        let mut c = 0;
        let mut m = 0;
        for r in &self.reports {
            b += r.stats.blanks;
            c += r.stats.code;
            m += r.stats.comments;
        }
        self.blanks = b;
        self.code = c;
        self.comments = m;
    }

    /// Summarised stats of this language including all of its children.
    pub fn summarise(&self) -> CodeStats {
        let mut s = CodeStats::new();
        for r in &self.reports {
            let x = r.stats.summarise();
            s.blanks += x.blanks;
            s.code += x.code;
            s.comments += x.comments;
        }
        s
    }

    pub fn is_empty(&self) -> bool {
        self.reports.is_empty()
    }
}
