//! The line counting state machine.

use crate::lang::{self, LangDef, LangId, Special};
use crate::stats::CodeStats;

#[derive(Clone, Copy, Default)]
pub struct ParseConfig {
    pub treat_doc_strings_as_comments: bool,
}

#[inline]
pub fn is_ws(b: u8) -> bool {
    matches!(b, b' ' | b'\t' | b'\n' | b'\r' | 0x0b | 0x0c)
}

pub fn trim(s: &[u8]) -> &[u8] {
    trim_end(trim_start(s))
}

pub fn trim_start(s: &[u8]) -> &[u8] {
    let mut i = 0;
    while i < s.len() && is_ws(s[i]) {
        i += 1;
    }
    &s[i..]
}

pub fn trim_end(s: &[u8]) -> &[u8] {
    let mut j = s.len();
    while j > 0 && is_ws(s[j - 1]) {
        j -= 1;
    }
    &s[..j]
}

fn find(hay: &[u8], needle: &[u8]) -> Option<usize> {
    if needle.is_empty() {
        return Some(0);
    }
    if needle.len() > hay.len() {
        return None;
    }
    let first = needle[0];
    let last_start = hay.len() - needle.len();
    let mut i = 0;
    while i <= last_start {
        match hay[i..=last_start].iter().position(|&b| b == first) {
            None => return None,
            Some(p) => {
                i += p;
                if &hay[i..i + needle.len()] == needle {
                    return Some(i);
                }
                i += 1;
            }
        }
    }
    None
}

fn contains(hay: &[u8], needle: &[u8]) -> bool {
    find(hay, needle).is_some()
}

/// Mirrors a slightly odd trimming routine: drops the first byte that is
/// either a newline or a non whitespace character (and everything before it),
/// and everything after the last newline / non whitespace byte.
pub fn trim_first_and_last_line_of_whitespace(s: &[u8]) -> &[u8] {
    let start = s
        .iter()
        .position(|&c| c == b'\n' || !is_ws(c))
        .map_or(0, |i| (i + 1).min(s.len().saturating_sub(1)));
    let end = s
        .iter()
        .rposition(|&c| c == b'\n' || !is_ws(c))
        .map_or_else(
            || s.len().saturating_sub(1),
            |i| {
                if i > 0 && s.get(i - 1) == Some(&b'\r') {
                    i - 1
                } else {
                    i
                }
            },
        );
    if s[start..].is_empty() {
        return &[];
    }
    if start > end + 1 {
        return &[];
    }
    &s[start..=end.min(s.len() - 1)]
}

struct LineStep {
    start: usize,
    end: usize,
}

impl LineStep {
    fn new(start: usize, end: usize) -> Self {
        LineStep { start, end }
    }
    fn next(&mut self, text: &[u8]) -> Option<(usize, usize)> {
        if self.start >= self.end {
            return None;
        }
        let s = self.start;
        let e = text[s..self.end]
            .iter()
            .position(|&b| b == b'\n')
            .map_or(self.end, |i| s + i);
        self.start = e + 1;
        Some((s, e))
    }
}

enum Ctx {
    Markdown { balanced: bool, language: LangId },
    Rust,
    Html { language: LangId },
    LinguaFranca,
}

struct FileContext {
    kind: Ctx,
    end: usize,
    stats: CodeStats,
}

struct Counter {
    def: &'static LangDef,
    important: Vec<&'static [u8]>,
    stack: Vec<&'static str>,
    quote: Option<&'static str>,
    quote_is_verbatim: bool,
    quote_is_doc: bool,
    lf_target: LangId,
}

impl Counter {
    fn new(id: LangId) -> Self {
        let def = lang::def(id);
        let mut important: Vec<&'static [u8]> = Vec::new();
        for (s, _) in def.quotes {
            important.push(s.as_bytes());
        }
        for (s, _) in def.doc_quotes {
            important.push(s.as_bytes());
        }
        for (s, _) in def.multi_line {
            important.push(s.as_bytes());
        }
        for (s, _) in def.nested_comments {
            important.push(s.as_bytes());
        }
        for s in def.important {
            important.push(s.as_bytes());
        }
        Counter {
            def,
            important,
            stack: Vec::new(),
            quote: None,
            quote_is_verbatim: false,
            quote_is_doc: false,
            lf_target: id,
        }
    }

    fn is_plain(&self) -> bool {
        self.quote.is_none() && self.stack.is_empty()
    }

    fn has_important(&self, line: &[u8]) -> bool {
        self.important.iter().any(|t| contains(line, t))
    }

    fn single_line(&self, line: &[u8], stats: &mut CodeStats) -> bool {
        if !self.is_plain() {
            return false;
        }
        if trim(line).is_empty() {
            stats.blanks += 1;
            return true;
        }
        if self.has_important(line) {
            return false;
        }
        if self.def.literate
            || self
                .def
                .line_comments
                .iter()
                .any(|c| line.starts_with(c.as_bytes()))
        {
            stats.comments += 1;
        } else {
            stats.code += 1;
        }
        true
    }

    fn parse_end_of_quote(&mut self, w: &[u8]) -> Option<usize> {
        if let Some(q) = self.quote {
            if w.starts_with(q.as_bytes()) {
                self.quote = None;
                return Some(q.len());
            }
        }
        if !self.quote_is_verbatim && w.starts_with(b"\\\\") {
            return Some(2);
        }
        if !self.quote_is_verbatim
            && w.starts_with(b"\\")
            && self
                .def
                .quotes
                .iter()
                .any(|(s, _)| w[1..].starts_with(s.as_bytes()))
        {
            return Some(2);
        }
        None
    }

    fn parse_end_of_multi_line(&mut self, w: &[u8]) -> Option<usize> {
        if let Some(last) = self.stack.last() {
            if w.starts_with(last.as_bytes()) {
                let l = last.len();
                self.stack.pop();
                return Some(l);
            }
        }
        None
    }

    fn parse_quote(&mut self, w: &[u8]) -> Option<usize> {
        if !self.stack.is_empty() {
            return None;
        }
        for (s, e) in self.def.doc_quotes {
            if w.starts_with(s.as_bytes()) {
                self.quote = Some(e);
                self.quote_is_verbatim = false;
                self.quote_is_doc = true;
                return Some(s.len());
            }
        }
        for (s, e) in self.def.verbatim_quotes {
            if w.starts_with(s.as_bytes()) {
                self.quote = Some(e);
                self.quote_is_verbatim = true;
                self.quote_is_doc = false;
                return Some(s.len());
            }
        }
        for (s, e) in self.def.quotes {
            if w.starts_with(s.as_bytes()) {
                self.quote = Some(e);
                self.quote_is_verbatim = false;
                self.quote_is_doc = false;
                return Some(s.len());
            }
        }
        None
    }

    fn parse_multi_line_comment(&mut self, w: &[u8]) -> Option<usize> {
        if self.quote.is_some() {
            return None;
        }
        let def = self.def;
        for (s, e) in def.multi_line.iter().chain(def.nested_comments.iter()) {
            if w.starts_with(s.as_bytes()) {
                if self.stack.is_empty()
                    || def.nested
                    || def.nested_comments.iter().any(|p| p.0 == *s && p.1 == *e)
                {
                    self.stack.push(e);
                }
                return Some(s.len());
            }
        }
        None
    }

    fn parse_line_comment(&self, w: &[u8]) -> bool {
        if self.quote.is_some() || !self.stack.is_empty() {
            return false;
        }
        self.def
            .line_comments
            .iter()
            .any(|c| w.starts_with(c.as_bytes()))
    }

    fn line_is_comment(&self, line: &[u8], cfg: &ParseConfig, started_in_comments: bool) -> bool {
        let t = trim(line);
        let def = self.def;
        if self.quote.is_some() {
            return self.quote_is_doc && cfg.treat_doc_strings_as_comments;
        }
        if started_in_comments {
            return true;
        }
        if def.line_comments.iter().any(|c| t.starts_with(c.as_bytes())) {
            return true;
        }
        if def
            .multi_line
            .iter()
            .chain(def.nested_comments.iter())
            .any(|(s, e)| t.starts_with(s.as_bytes()) && t.ends_with(e.as_bytes()))
        {
            return true;
        }
        if let Some(last) = self.stack.last() {
            if def
                .multi_line
                .iter()
                .chain(def.nested_comments.iter())
                .any(|(s, e)| e == last && t.starts_with(s.as_bytes()))
            {
                return true;
            }
        }
        false
    }

    /// Returns Ok(ended_with_comments) or a child context.
    fn multi_line_analysis(
        &mut self,
        text: &[u8],
        start: usize,
        end: usize,
        cfg: &ParseConfig,
    ) -> Result<bool, FileContext> {
        let mut ended = false;
        let mut skip = 0usize;
        for i in start..end {
            if skip != 0 {
                skip -= 1;
                continue;
            }
            let w = &text[i..end];
            if trim(w).is_empty() && trim(&text[i..]).is_empty() {
                break;
            }
            ended = false;
            let r = match self.parse_end_of_quote(w) {
                Some(n) => Some(n),
                None => self.parse_end_of_multi_line(w),
            };
            if let Some(n) = r {
                ended = true;
                skip = n - 1;
                continue;
            } else if self.quote.is_some() {
                continue;
            }
            if let Some(ctx) = self.parse_context(text, i, end, cfg) {
                return Err(ctx);
            }
            let r = match self.parse_quote(w) {
                Some(n) => Some(n),
                None => self.parse_multi_line_comment(w),
            };
            if let Some(n) = r {
                skip = n - 1;
                continue;
            }
            if self.parse_line_comment(w) {
                ended = true;
                break;
            }
        }
        Ok(ended)
    }

    fn parse_context(
        &mut self,
        text: &[u8],
        start: usize,
        _end: usize,
        cfg: &ParseConfig,
    ) -> Option<FileContext> {
        if self.quote.is_some() || !self.stack.is_empty() {
            return None;
        }
        match self.def.special {
            Special::Markdown => markdown_context(text, start, cfg),
            Special::Rust => rust_context(text, start, cfg),
            Special::Html => html_context(text, start, cfg),
            Special::LinguaFranca => lf_context(text, start, self.lf_target, cfg),
            _ => None,
        }
    }
}

fn markdown_context(text: &[u8], start: usize, cfg: &ParseConfig) -> Option<FileContext> {
    let w = &text[start..];
    if !w.starts_with(b"```") {
        return None;
    }
    let ident_start = start + 3;
    let mut ident_end = ident_start;
    while ident_end < text.len() && !is_ws(text[ident_end]) {
        ident_end += 1;
    }
    let ident = &text[ident_start..ident_end];
    let first = ident.split(|&b| b == b',').next().unwrap_or(&[]);
    let first = String::from_utf8_lossy(first);
    let language = lang::from_name(first.trim())?;
    let closing = find(&text[ident_end..], b"```").map(|p| p + ident_end);
    let (end_of_code, end_of_block, balanced) = match closing {
        Some(c) => {
            let mut e = c + 3;
            if e < text.len() && text[e] == b'\n' {
                e += 1;
            }
            (c, e, true)
        }
        None => (text.len(), text.len(), false),
    };
    let content = trim(&text[ident_end..end_of_code]);
    let stats = parse(language, content, cfg);
    Some(FileContext {
        kind: Ctx::Markdown { balanced, language },
        end: end_of_block,
        stats,
    })
}

fn rust_context(text: &[u8], start: usize, cfg: &ParseConfig) -> Option<FileContext> {
    let w = &text[start..];
    if !(w.starts_with(b"///") || w.starts_with(b"//!")) {
        return None;
    }
    let mut stepper = LineStep::new(start, text.len());
    let mut md: Vec<u8> = Vec::new();
    let mut end_of_block = text.len();
    while let Some((s, e)) = stepper.next(text) {
        let l = trim_start(&text[s..e]);
        if l.starts_with(b"///") || l.starts_with(b"//!") {
            md.extend_from_slice(&l[3..]);
            md.push(b'\n');
            end_of_block = e;
        } else if l.is_empty() {
            continue;
        } else {
            break;
        }
    }
    let stats = parse(lang_markdown(), trim(&md), cfg);
    Some(FileContext {
        kind: Ctx::Rust,
        end: end_of_block + 1,
        stats,
    })
}

fn lang_markdown() -> LangId {
    lang::from_name("Markdown").unwrap()
}

/// Emulates `<tag(?:.*attr="(.*)")?.*?>` matched against a single line.
/// `line` is the text following `<tag`. Returns (capture, match_end_offset).
fn match_tag(line: &[u8], attr: &[u8]) -> Option<(Option<&[u8]>, usize)> {
    let mut pat = attr.to_vec();
    pat.extend_from_slice(b"=\"");
    // Positions of the attribute occurrences.
    let mut occ = Vec::new();
    let mut i = 0;
    while let Some(p) = find(&line[i..], &pat) {
        occ.push(i + p);
        i += p + 1;
    }
    for &p in occ.iter().rev() {
        let after = p + pat.len();
        // capture greedy: the largest q >= after with line[q] == '"' such that a '>' follows.
        let mut q = line.len();
        while q > after {
            q -= 1;
            if line[q] == b'"' {
                if let Some(gt) = line[q + 1..].iter().position(|&b| b == b'>') {
                    return Some((Some(&line[after..q]), q + 1 + gt + 1));
                }
            }
        }
        if q == after {
            // no candidate quote for this occurrence
        }
    }
    let gt = line.iter().position(|&b| b == b'>')?;
    Some((None, gt + 1))
}

fn html_context(text: &[u8], start: usize, cfg: &ParseConfig) -> Option<FileContext> {
    let w = &text[start..];
    let line_end = w.iter().position(|&b| b == b'\n').unwrap_or(w.len());
    let (tag, attr, close, kind): (&[u8], &[u8], &[u8], u8) = if w.starts_with(b"<script") {
        (b"<script", b"type", b"</script>", 0)
    } else if w.starts_with(b"<style") {
        (b"<style", b"lang", b"</style>", 1)
    } else if w.starts_with(b"<template") {
        (b"<template", b"lang", b"</template>", 2)
    } else {
        return None;
    };
    let line = &w[tag.len()..line_end];
    let (cap, mend) = match_tag(line, attr)?;
    let start_of_code = start + tag.len() + mend;
    let close_pos = find(&text[start_of_code..], close)? + start_of_code;
    let language = match kind {
        0 => cap
            .and_then(|c| lang::from_mime(&String::from_utf8_lossy(trim(c))))
            .unwrap_or_else(|| lang::from_name("JavaScript").unwrap()),
        1 => cap
            .and_then(|c| lang::from_name(&String::from_utf8_lossy(trim(c))))
            .unwrap_or_else(|| lang::from_name("CSS").unwrap()),
        _ => cap
            .and_then(|c| lang::from_name(&String::from_utf8_lossy(trim(c))))
            .unwrap_or_else(|| lang::from_name("HTML").unwrap()),
    };
    let contents = &text[start_of_code..close_pos];
    if trim(contents).is_empty() {
        return None;
    }
    let stats = parse(language, trim_first_and_last_line_of_whitespace(contents), cfg);
    Some(FileContext {
        kind: Ctx::Html { language },
        end: close_pos,
        stats,
    })
}

fn lf_context(text: &[u8], start: usize, target: LangId, cfg: &ParseConfig) -> Option<FileContext> {
    let w = &text[start..];
    if !w.starts_with(b"{=") {
        return None;
    }
    let code_start = start + 2;
    let close = find(&text[code_start..], b"=}")? + code_start;
    let contents = &text[code_start..close];
    let stats = parse(target, trim_first_and_last_line_of_whitespace(contents), cfg);
    let mut e = close + 2;
    if e < text.len() && text[e] == b'\n' {
        e += 1;
    }
    Some(FileContext {
        kind: Ctx::LinguaFranca,
        end: e,
        stats,
    })
}

fn is_word(b: u8) -> bool {
    b.is_ascii_alphanumeric() || b == b'_'
}

fn find_lf_target(text: &[u8], own: LangId) -> LangId {
    let mut i = 0;
    while let Some(p) = find(&text[i..], b"target") {
        let pos = i + p;
        let mut j = pos + 6;
        let ws_start = j;
        while j < text.len() && is_ws(text[j]) {
            j += 1;
        }
        if j > ws_start {
            let ws = j;
            while j < text.len() && is_word(text[j]) {
                j += 1;
            }
            if j > ws {
                let word = &text[ws..j];
                return match word {
                    b"C" => lang::from_name("C").unwrap(),
                    b"CCpp" | b"Cpp" => lang::from_name("C++").unwrap(),
                    b"Python" => lang::from_name("Python").unwrap(),
                    b"TypeScript" => lang::from_name("TypeScript").unwrap(),
                    b"Rust" => lang::from_name("Rust").unwrap(),
                    _ => own,
                };
            }
        }
        i = pos + 1;
    }
    own
}

pub fn parse(id: LangId, text: &[u8], cfg: &ParseConfig) -> CodeStats {
    let def = lang::def(id);
    if def.special == Special::Jupyter {
        return crate::jupyter::parse_jupyter(text, cfg).unwrap_or_default();
    }
    let mut counter = Counter::new(id);
    if def.special == Special::LinguaFranca {
        counter.lf_target = find_lf_target(text, id);
    }
    parse_lines(&mut counter, text, cfg)
}

fn parse_lines(c: &mut Counter, text: &[u8], cfg: &ParseConfig) -> CodeStats {
    let mut stats = CodeStats::new();
    let mut stepper = LineStep::new(0, text.len());
    while let Some((s, e)) = stepper.next(text) {
        let raw = &text[s..e];
        let line = if c.def.fortran { raw } else { trim(raw) };
        if c.single_line(line, &mut stats) {
            continue;
        }
        let started = !c.stack.is_empty()
            || (cfg.treat_doc_strings_as_comments && c.quote.is_some() && c.quote_is_doc);
        match c.multi_line_analysis(text, s, e, cfg) {
            Ok(_ended) => {}
            Err(ctx) => {
                match ctx.kind {
                    Ctx::Markdown { balanced, language } => {
                        stats.comments += if balanced { 2 } else { 1 };
                        stats.blobs.entry(language).or_default().add(&ctx.stats);
                    }
                    Ctx::Rust => {
                        stats.blobs.entry(lang_markdown()).or_default().add(&ctx.stats);
                    }
                    Ctx::LinguaFranca => {
                        stats.code += 1;
                        stats.blobs.entry(c.lf_target).or_default().add(&ctx.stats);
                    }
                    Ctx::Html { language } => {
                        stats.code += 1;
                        stats.blobs.entry(language).or_default().add(&ctx.stats);
                    }
                }
                stepper = LineStep::new(ctx.end, text.len());
                continue;
            }
        }
        if c.def.literate || c.line_is_comment(line, cfg, started) {
            stats.comments += 1;
        } else {
            stats.code += 1;
        }
    }
    stats
}
