//! Jupyter notebook support.

use crate::json::{self, Value};
use crate::lang;
use crate::stats::CodeStats;
use crate::syntax::{parse, ParseConfig};

pub fn parse_jupyter(text: &[u8], cfg: &ParseConfig) -> Option<CodeStats> {
    let root = json::parse(text)?;
    let obj = match &root {
        Value::Object(o) => o,
        _ => return None,
    };
    // Required fields, no duplicates allowed.
    let mut cells = None;
    let mut metadata = None;
    for (k, v) in obj {
        match k.as_str() {
            "cells" => {
                if cells.is_some() {
                    return None;
                }
                cells = Some(v);
            }
            "metadata" => {
                if metadata.is_some() {
                    return None;
                }
                metadata = Some(v);
            }
            _ => {}
        }
    }
    let cells = match cells? {
        Value::Array(a) => a,
        _ => return None,
    };
    let metadata = match metadata? {
        Value::Object(o) => o,
        _ => return None,
    };
    let mut kernelspec = None;
    let mut language_info = None;
    for (k, v) in metadata {
        match k.as_str() {
            "kernelspec" => {
                if kernelspec.is_some() {
                    return None;
                }
                kernelspec = Some(v);
            }
            "language_info" => {
                if language_info.is_some() {
                    return None;
                }
                language_info = Some(v);
            }
            _ => {}
        }
    }
    let kernelspec = kernelspec?;
    language_info?;

    let python = lang::from_name("Python").unwrap();
    let markdown = lang::from_name("Markdown").unwrap();
    let language = kernelspec
        .get("language")
        .and_then(|v| v.as_str())
        .and_then(lang::from_name)
        .unwrap_or(python);

    let mut parsed: Vec<(bool, String)> = Vec::new();
    for cell in cells {
        let o = match cell {
            Value::Object(o) => o,
            _ => return None,
        };
        let mut ct = None;
