//! Gitignore style glob matching.

#[derive(Debug, Clone)]
enum Tok {
    Lit(u8),
    Any,  // *
    One,  // ?
    Class { neg: bool, items: Vec<(u32, u32)> },
    RecPrefix, // **/ at the beginning
    RecSuffix, // /** at the end
    RecZeroOrMore, // /**/ in the middle
    RecAll,    // ** that is the whole glob
    Alt(Vec<Vec<Tok>>),
}

#[derive(Debug, Clone)]
pub struct Glob {
    toks: Vec<Tok>,
}

fn decode_char(s: &[u8], i: usize) -> (u32, usize) {
    let b = s[i];
    let len = if b < 0x80 {
        1
    } else if b >> 5 == 0b110 {
        2
    } else if b >> 4 == 0b1110 {
        3
    } else if b >> 3 == 0b11110 {
        4
    } else {
        1
    };
    if i + len > s.len() {
        return (b as u32, 1);
    }
    match std::str::from_utf8(&s[i..i + len]) {
        Ok(st) => (st.chars().next().unwrap() as u32, len),
        Err(_) => (b as u32, 1),
    }
}

impl Glob {
    pub fn new(pat: &str) -> Option<Glob> {
        let b = pat.as_bytes();
        let (toks, i) = parse_seq(b, 0, false)?;
        if i != b.len() {
            return None;
        }
        Some(Glob { toks })
    }

    pub fn is_match(&self, path: &[u8]) -> bool {
        match_toks(&self.toks, path)
    }
}

fn parse_seq(b: &[u8], mut i: usize, in_alt: bool) -> Option<(Vec<Tok>, usize)> {
    let mut toks = Vec::new();
    while i < b.len() {
        let c = b[i];
        if in_alt && (c == b',' || c == b'}') {
            break;
        }
        match c {
            b'\\' => {
                if i + 1 < b.len() {
                    let (_, l) = decode_char(b, i + 1);
                    for k in 0..l {
                        toks.push(Tok::Lit(b[i + 1 + k]));
                    }
                    i += 1 + l;
                } else {
                    // trailing backslash: invalid escape in globset
                    return None;
                }
            }
            b'?' => {
                toks.push(Tok::One);
                i += 1;
            }
            b'*' => {
                if i + 1 < b.len() && b[i + 1] == b'*' {
                    // double star
                    let at_start = i == 0 || (b[i - 1] == b'/');
                    let after = i + 2;
                    let at_end = after == b.len() || (in_alt && (b[after] == b',' || b[after] == b'}'));
                    let followed_by_slash = after < b.len() && b[after] == b'/';
                    let prev_is_slash = i > 0 && b[i - 1] == b'/';
                    if i == 0 && at_end {
                        toks.push(Tok::RecAll);
                        i = after;
                    } else if i == 0 && followed_by_slash {
                        toks.push(Tok::RecPrefix);
                        i = after + 1;
                    } else if prev_is_slash && at_end {
                        // remove the previous '/' literal
                        if let Some(Tok::Lit(b'/')) = toks.last() {
                            toks.pop();
                        }
                        toks.push(Tok::RecSuffix);
                        i = after;
                    } else if prev_is_slash && followed_by_slash {
                        if let Some(Tok::Lit(b'/')) = toks.last() {
                            toks.pop();
                        }
                        toks.push(Tok::RecZeroOrMore);
                        i = after + 1;
                    } else if at_start && at_end {
                        toks.push(Tok::RecAll);
                        i = after;
                    } else {
                        // Not a valid recursive wildcard, treat as single star(s).
                        toks.push(Tok::Any);
                        i = after;
                    }
                } else {
                    toks.push(Tok::Any);
                    i += 1;
                }
            }
            b'[' => {
                let (tok, ni) = parse_class(b, i)?;
                toks.push(tok);
                i = ni;
            }
            b'{' => {
                let mut alts = Vec::new();
                let mut j = i + 1;
                loop {
                    let (seq, nj) = parse_seq(b, j, true)?;
                    alts.push(seq);
                    if nj >= b.len() {
                        return None;
                    }
                    if b[nj] == b',' {
                        j = nj + 1;
                        continue;
                    }
                    // '}'
                    i = nj + 1;
                    break;
                }
                toks.push(Tok::Alt(alts));
            }
            _ => {
                toks.push(Tok::Lit(c));
                i += 1;
            }
        }
    }
    Some((toks, i))
}

fn parse_class(b: &[u8], start: usize) -> Option<(Tok, usize)> {
    let mut i = start + 1;
    let mut neg = false;
    if i < b.len() && (b[i] == b'!' || b[i] == b'^') {
        neg = true;
        i += 1;
    }
    let mut items: Vec<(u32, u32)> = Vec::new();
    let mut first = true;
    loop {
        if i >= b.len() {
            return None;
        }
        if b[i] == b']' && !first {
            i += 1;
            break;
        }
        first = false;
        let (c, l) = if b[i] == b'\\' && i + 1 < b.len() {
            let (c, l) = decode_char(b, i + 1);
            (c, l + 1)
        } else {
            decode_char(b, i)
        };
        i += l;
        if i + 1 < b.len() && b[i] == b'-' && b[i + 1] != b']' {
            let (c2, l2) = decode_char(b, i + 1);
            i += 1 + l2;
            if c2 < c {
                return None;
            }
            items.push((c, c2));
        } else {
            items.push((c, c));
        }
    }
    Some((Tok::Class { neg, items }, i))
}

fn match_toks(toks: &[Tok], s: &[u8]) -> bool {
    if toks.is_empty() {
        return s.is_empty();
    }
    match &toks[0] {
        Tok::Lit(c) => !s.is_empty() && s[0] == *c && match_toks(&toks[1..], &s[1..]),
        Tok::One => {
            if s.is_empty() || s[0] == b'/' {
                return false;
            }
            let (_, l) = decode_char(s, 0);
            match_toks(&toks[1..], &s[l..])
        }
        Tok::Class { neg, items } => {
            if s.is_empty() {
                return false;
            }
            let (c, l) = decode_char(s, 0);
            if c == '/' as u32 {
                return false;
            }
            let inside = items.iter().any(|(a, b)| c >= *a && c <= *b);
            if inside == *neg {
                return false;
            }
            match_toks(&toks[1..], &s[l..])
        }
        Tok::Any => {
            let mut k = 0;
            loop {
                if match_toks(&toks[1..], &s[k..]) {
                    return true;
                }
                if k >= s.len() || s[k] == b'/' {
                    return false;
                }
                k += 1;
            }
        }
        Tok::RecAll => true,
        Tok::RecPrefix => {
            // matches empty or any prefix ending in '/'
            if match_toks(&toks[1..], s) {
                return true;
            }
            for k in 0..s.len() {
                if s[k] == b'/' && match_toks(&toks[1..], &s[k + 1..]) {
                    return true;
                }
            }
            false
        }
        Tok::RecSuffix => {
            // '/' followed by anything
            !s.is_empty() && s[0] == b'/' && toks.len() == 1
                || (!s.is_empty() && s[0] == b'/' && {
                    let rest = &toks[1..];
                    (1..=s.len()).any(|k| match_toks(rest, &s[k..]))
                })
        }
        Tok::RecZeroOrMore => {
            // '/' or '/.../'
            if s.is_empty() || s[0] != b'/' {
                return false;
            }
            if match_toks(&toks[1..], &s[1..]) {
                return true;
            }
            for k in 1..s.len() {
                if s[k] == b'/' && match_toks(&toks[1..], &s[k + 1..]) {
                    return true;
                }
            }
            false
        }
        Tok::Alt(alts) => {
            for a in alts {
                let mut combined = a.clone();
                combined.extend_from_slice(&toks[1..]);
                if match_toks(&combined, s) {
                    return true;
                }
            }
            false
        }
    }
}

/// A single gitignore rule.
#[derive(Debug, Clone)]
pub struct Rule {
    pub glob: Glob,
    pub whitelist: bool,
    pub only_dir: bool,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Match {
    None,
    Ignore,
    Whitelist,
}

impl Match {
    pub fn is_none(&self) -> bool {
        *self == Match::None
    }
    pub fn or(self, other: Match) -> Match {
        if self.is_none() {
            other
        } else {
            self
        }
    }
}

/// A compiled gitignore file.
#[derive(Debug, Clone, Default)]
pub struct Gitignore {
    /// Root directory (with a leading "./" stripped).
    pub root: Vec<u8>,
    pub rules: Vec<Rule>,
}

pub fn strip_prefix<'a>(prefix: &[u8], path: &'a [u8]) -> Option<&'a [u8]> {
    if path.starts_with(prefix) {
        Some(&path[prefix.len()..])
    } else {
        None
    }
}

impl Gitignore {
    pub fn new(root: &[u8]) -> Gitignore {
        let root = strip_prefix(b"./", root).unwrap_or(root).to_vec();
        Gitignore { root, rules: Vec::new() }
    }

    pub fn add_line(&mut self, line: &str) {
        let mut line = line;
        if line.starts_with('#') {
            return;
        }
        if !line.ends_with("\\ ") {
            line = line.trim_end();
        }
        if line.is_empty() {
            return;
        }
        let mut whitelist = false;
        let mut only_dir = false;
        let mut is_absolute = false;
        if line.starts_with("\\!") || line.starts_with("\\#") {
            line = &line[1..];
            is_absolute = line.starts_with('/');
        } else {
            if let Some(l) = line.strip_prefix('!') {
                whitelist = true;
                line = l;
            }
            if let Some(l) = line.strip_prefix('/') {
                line = l;
                is_absolute = true;
            }
        }
        if line.ends_with('/') {
            only_dir = true;
            line = &line[..line.len() - 1];
            if line.ends_with('\\') {
                line = &line[..line.len() - 1];
            }
        }
        let mut actual = line.to_string();
        if !is_absolute && !line.contains('/') && !actual.starts_with("**/") {
            actual = format!("**/{}", actual);
        }
        if actual.ends_with("/**") {
            actual.push_str("/*");
        }
        if let Some(glob) = Glob::new(&actual) {
            self.rules.push(Rule { glob, whitelist, only_dir });
        }
    }

    pub fn from_file(root: &[u8], path: &std::path::Path) -> Option<Gitignore> {
        let data = std::fs::read(path).ok()?;
        let mut gi = Gitignore::new(root);
        let text = String::from_utf8_lossy(&data);
        for line in text.lines() {
            gi.add_line(line);
        }
        Some(gi)
    }

    pub fn is_empty(&self) -> bool {
        self.rules.is_empty()
    }

    fn strip<'a>(&self, path: &'a [u8]) -> &'a [u8] {
        let mut path = path;
        if let Some(p) = strip_prefix(b"./", path) {
            path = p;
        }
        let is_file_name = !path.contains(&b'/');
        if self.root.as_slice() != b"." && !is_file_name {
            if let Some(p) = strip_prefix(&self.root, path) {
                path = p;
                if let Some(p) = strip_prefix(b"/", path) {
                    path = p;
                }
            }
        }
        path
    }

    pub fn matched(&self, path: &[u8], is_dir: bool) -> Match {
        if self.is_empty() {
            return Match::None;
        }
        let path = self.strip(path);
        for rule in self.rules.iter().rev() {
            if rule.only_dir && !is_dir {
                continue;
            }
            if rule.glob.is_match(path) {
                return if rule.whitelist { Match::Whitelist } else { Match::Ignore };
            }
        }
        Match::None
    }
}
