//! Directory traversal honouring ignore files.

use crate::glob::{strip_prefix, Gitignore, Match};
use std::os::unix::ffi::OsStrExt;
use std::path::{Path, PathBuf};

#[derive(Clone, Default)]
pub struct WalkOptions {
    pub hidden: bool,
    pub no_ignore: bool,
    pub no_ignore_parent: bool,
    pub no_ignore_dot: bool,
    pub no_ignore_vcs: bool,
    pub excludes: Vec<String>,
}

struct DirIgnore {
    dir: Vec<u8>,
    custom: Gitignore,
    ignore: Gitignore,
    git: Gitignore,
    exclude: Gitignore,
    has_git: bool,
}

struct Opts {
    hidden: bool,
    ignore_dot: bool,
    ignore_vcs: bool,
    parents: bool,
}

pub struct Walker {
    opts: Opts,
    overrides: Gitignore,
    global: Gitignore,
    pub files: Vec<PathBuf>,
}

fn load(root: &[u8], dir: &Path, name: &str, enabled: bool) -> Gitignore {
    if !enabled {
        return Gitignore::new(root);
    }
    let p = dir.join(name);
    Gitignore::from_file(root, &p).unwrap_or_else(|| Gitignore::new(root))
}

fn home_dir() -> Option<PathBuf> {
    std::env::var_os("HOME").map(PathBuf::from)
}

fn global_gitignore_path() -> Option<PathBuf> {
    // core.excludesFile from git config files
    let mut candidates = Vec::new();
    if let Some(xdg) = std::env::var_os("XDG_CONFIG_HOME") {
        candidates.push(PathBuf::from(xdg).join("git/config"));
    } else if let Some(h) = home_dir() {
        candidates.push(h.join(".config/git/config"));
    }
    if let Some(h) = home_dir() {
        candidates.push(h.join(".gitconfig"));
    }
    let mut found: Option<String> = None;
    for c in candidates {
        if let Ok(text) = std::fs::read_to_string(&c) {
            let mut in_core = false;
            for line in text.lines() {
                let t = line.trim();
                if t.starts_with('[') {
                    in_core = t.trim_start_matches('[').trim_end_matches(']').trim().eq_ignore_ascii_case("core");
                    continue;
                }
                if in_core {
                    if let Some((k, v)) = t.split_once('=') {
                        if k.trim().eq_ignore_ascii_case("excludesfile") {
                            found = Some(v.trim().trim_matches('"').to_string());
                        }
                    }
                }
            }
        }
    }
    if let Some(f) = found {
        if let Some(rest) = f.strip_prefix("~/") {
            return home_dir().map(|h| h.join(rest));
        }
        return Some(PathBuf::from(f));
    }
    if let Some(xdg) = std::env::var_os("XDG_CONFIG_HOME") {
        if !xdg.is_empty() {
            return Some(PathBuf::from(xdg).join("git/ignore"));
        }
    }
    home_dir().map(|h| h.join(".config/git/ignore"))
}

impl Walker {
    pub fn new(o: &WalkOptions) -> Walker {
        let ignore = !o.no_ignore;
        let ignore_dot = ignore && !o.no_ignore_dot;
        let ignore_vcs = ignore && !o.no_ignore_vcs;
        let opts = Opts {
            hidden: !o.hidden,
            ignore_dot,
            ignore_vcs,
            parents: ignore && !o.no_ignore_parent,
        };
        let mut overrides = Gitignore::new(b".");
        for e in &o.excludes {
            overrides.add_line(&format!("!{}", e));
        }
        // Overrides are inverted: "!pat" in override syntax means ignore.
        for r in overrides.rules.iter_mut() {
            r.whitelist = !r.whitelist;
        }
        let mut global = Gitignore::new(b".");
        if ignore_vcs {
            if let Some(p) = global_gitignore_path() {
                let cwd = std::env::current_dir().unwrap_or_default();
                if let Some(g) = Gitignore::from_file(cwd.as_os_str().as_bytes(), &p) {
                    global = g;
                }
            }
        }
        Walker { opts, overrides, global, files: Vec::new() }
    }

    fn dir_ignore(&self, dir_bytes: &[u8], dir: &Path) -> DirIgnore {
        let has_git = self.opts.ignore_vcs && dir.join(".git").exists();
        let exclude = if self.opts.ignore_vcs {
            Gitignore::from_file(dir_bytes, &dir.join(".git/info/exclude"))
                .unwrap_or_else(|| Gitignore::new(dir_bytes))
        } else {
            Gitignore::new(dir_bytes)
        };
        DirIgnore {
            dir: dir_bytes.to_vec(),
            custom: load(dir_bytes, dir, ".tokeignore", self.opts.ignore_dot),
            ignore: load(dir_bytes, dir, ".ignore", self.opts.ignore_dot),
            git: load(dir_bytes, dir, ".gitignore", self.opts.ignore_vcs),
            exclude,
            has_git,
        }
    }

    /// Walks a root path. Calls `on_error` for directory read errors.
    pub fn walk_root(&mut self, root: &Path, on_error: &mut dyn FnMut(String)) {
        // Parents
        let mut parents: Vec<DirIgnore> = Vec::new();
        let mut abs_root: Vec<u8> = Vec::new();
        if let Ok(abs) = root.canonicalize() {
            abs_root = abs.as_os_str().as_bytes().to_vec();
            let mut p = abs.as_path();
            while let Some(parent) = p.parent() {
                let pb = parent.as_os_str().as_bytes().to_vec();
                parents.push(self.dir_ignore(&pb, parent));
                p = parent;
            }
        }
        let mut chain: Vec<DirIgnore> = Vec::new();
        self.walk_dir(root, &mut chain, &parents, &abs_root, on_error);
    }

    fn matched(
        &self,
        path: &[u8],
        name: &[u8],
        is_dir: bool,
        chain: &[DirIgnore],
        parents: &[DirIgnore],
        abs_root: &[u8],
    ) -> bool {
        let path = strip_prefix(b"./", path).unwrap_or(path);
        // overrides
        if !self.overrides.is_empty() {
            match self.overrides.matched(path, is_dir) {
                Match::Ignore => return true,
                Match::Whitelist => return false,
                Match::None => {}
            }
        }
        let mut whitelisted = false;
        let any_git = chain.iter().any(|d| d.has_git) || parents.iter().any(|d| d.has_git);
        let (mut mc, mut mi, mut mg, mut me) = (Match::None, Match::None, Match::None, Match::None);
        let mut saw_git = false;
        for ig in chain.iter().rev() {
            if mc.is_none() {
                mc = ig.custom.matched(path, is_dir);
            }
            if mi.is_none() {
                mi = ig.ignore.matched(path, is_dir);
            }
            if any_git && !saw_git && mg.is_none() {
                mg = ig.git.matched(path, is_dir);
            }
            if any_git && !saw_git && me.is_none() {
                me = ig.exclude.matched(path, is_dir);
            }
            saw_git = saw_git || ig.has_git;
        }
        if self.opts.parents && !abs_root.is_empty() {
            if let Some(cur) = chain.last() {
                let dirpath = cur.dir.as_slice();
                let prefix = strip_prefix(b"./", dirpath).unwrap_or(dirpath);
                let rel = match strip_prefix(prefix, path) {
                    None => path,
                    Some(p) => strip_prefix(b"/", p).unwrap_or(p),
                };
                let mut abs = abs_root.to_vec();
                if !rel.is_empty() {
                    if !abs.ends_with(b"/") {
                        abs.push(b'/');
                    }
                    abs.extend_from_slice(rel);
                }
                for ig in parents.iter() {
                    if mc.is_none() {
                        mc = ig.custom.matched(&abs, is_dir);
                    }
                    if mi.is_none() {
                        mi = ig.ignore.matched(&abs, is_dir);
                    }
                    if any_git && !saw_git && mg.is_none() {
                        mg = ig.git.matched(&abs, is_dir);
                    }
                    if any_git && !saw_git && me.is_none() {
                        me = ig.exclude.matched(&abs, is_dir);
                    }
                    saw_git = saw_git || ig.has_git;
                }
            }
        }
        let mglobal = if any_git { self.global.matched(path, is_dir) } else { Match::None };
        let m = mc.or(mi).or(mg).or(me).or(mglobal);
        match m {
            Match::Ignore => return true,
            Match::Whitelist => whitelisted = true,
            Match::None => {}
        }
        let _ = name;
        if !whitelisted && self.opts.hidden {
            let fname = path.rsplit(|&b| b == b'/').next().unwrap_or(path);
            if fname.starts_with(b".") {
                return true;
            }
        }
        false
    }

    fn walk_dir(
        &mut self,
        dir: &Path,
        chain: &mut Vec<DirIgnore>,
        parents: &[DirIgnore],
        abs_root: &[u8],
        on_error: &mut dyn FnMut(String),
    ) {
        let rd = match std::fs::read_dir(dir) {
            Ok(r) => r,
            Err(e) => {
                on_error(format!("{} reading {}", e, dir.display()));
                return;
            }
        };
        let dir_bytes = dir.as_os_str().as_bytes().to_vec();
        chain.push(self.dir_ignore(&dir_bytes, dir));
        let mut entries: Vec<(PathBuf, bool, bool)> = Vec::new();
        for ent in rd {
            let ent = match ent {
                Ok(e) => e,
                Err(e) => {
                    on_error(format!("{} reading {}", e, dir.display()));
                    continue;
                }
            };
            let ft = match ent.file_type() {
                Ok(f) => f,
                Err(_) => continue,
            };
            let path = dir.join(ent.file_name());
            entries.push((path, ft.is_dir(), ft.is_file()));
        }
        entries.sort();
        for (path, is_dir, is_file) in entries {
            let pb = path.as_os_str().as_bytes().to_vec();
            let name = path.file_name().map(|n| n.as_bytes().to_vec()).unwrap_or_default();
            if self.matched(&pb, &name, is_dir, chain, parents, abs_root) {
                continue;
            }
            if is_dir {
                self.walk_dir(&path, chain, parents, abs_root, on_error);
            } else if is_file {
                self.files.push(path);
            }
        }
        chain.pop();
    }
}
