//! Command line parsing, mimicking clap's behaviour and messages.

use std::fmt::Write as _;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Sort {
    Files,
    Lines,
    Blanks,
    Code,
    Comments,
}

impl Sort {
    pub fn from_str_ci(s: &str) -> Option<Sort> {
        match s.to_lowercase().as_str() {
            "files" => Some(Sort::Files),
            "lines" => Some(Sort::Lines),
            "blanks" => Some(Sort::Blanks),
            "code" => Some(Sort::Code),
            "comments" => Some(Sort::Comments),
            _ => None,
        }
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum NumFormat {
    Commas,
    Dots,
    Plain,
    Underscores,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Streaming {
