];

pub const VERSION: &str = "tokei 14.0.0 compiled with serialization support: json";

pub enum Outcome {
    Run(Cli),
    Help,
    Version,
    Error(String),
}

fn display(a: &ArgDef) -> String {
    match a.kind {
        Kind::Opt => format!("--{} <{}>", a.long, a.value_name),
        _ => format!("--{}", a.long),
    }
}

pub fn jaro(a: &str, b: &str) -> f64 {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    let (al, bl) = (a.len(), b.len());
    if al == 0 && bl == 0 {
        return 1.0;
    }
    if al == 0 || bl == 0 {
        return 0.0;
    }
    let mut range = std::cmp::max(al, bl) / 2;
    range = range.saturating_sub(1);
    let mut af = vec![false; al];
    let mut bf = vec![false; bl];
    let mut matches = 0usize;
    for i in 0..al {
        let lo = if i > range { i - range } else { 0 };
        let hi = std::cmp::min(bl, i + range + 1);
        for j in 0..hi {
            if lo <= j && a[i] == b[j] && !bf[j] {
                af[i] = true;
                bf[j] = true;
                matches += 1;
                break;
            }
        }
    }
    if matches == 0 {
        return 0.0;
    }
    let mut trans = 0usize;
    let mut k = 0usize;
    for i in 0..al {
        if af[i] {
            while k < bl && !bf[k] {
                k += 1;
            }
            if k < bl {
                if a[i] != b[k] {
                    trans += 1;
                }
                k += 1;
            }
        }
    }
    trans /= 2;
    let m = matches as f64;
    (m / al as f64 + m / bl as f64 + (m - trans as f64) / m) / 3.0
}

fn did_you_mean<'a>(v: &str, cands: impl Iterator<Item = &'a str>) -> Option<String> {
    let mut c: Vec<(f64, String)> = cands
        .map(|p| (jaro(v, p), p.to_string()))
        .filter(|(conf, _)| *conf > 0.7)
        .collect();
    c.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap_or(std::cmp::Ordering::Equal));
    c.pop().map(|x| x.1)
}

struct Parser {
    bin: String,
    seen: Vec<usize>, // order of first occurrence of arg indexes
    counts: Vec<usize>,
    values: Vec<Vec<String>>,
    input: Vec<String>,
}

enum Pending {
    None,
    Wanting(usize),
    Have(usize, String),
}

impl Parser {
    fn usage_generic(&self) -> String {
        format!("Usage: {} [OPTIONS] [input]...", self.bin)
    }

    fn err_footer(&self) -> &'static str {
        "For more information, try '--help'.\n"
    }

    fn unexpected(&self, tok: &str, suggestion: Option<&ArgDef>) -> String {
        let mut s = format!("error: unexpected argument '{}' found\n\n", tok);
        match suggestion {
            Some(a) => {
                let _ = write!(s, "  tip: a similar argument exists: '--{}'\n\n", a.long);
                let _ = write!(s, "Usage: {} {} [input]...\n\n", self.bin, display(a));
            }
            None => {
                let _ = write!(s, "  tip: to pass '{}' as a value, use '-- {}'\n\n", tok, tok);
                let _ = write!(s, "{}\n\n", self.usage_generic());
            }
        }
        s.push_str(self.err_footer());
        s
    }

    fn missing_value(&self, a: &ArgDef) -> String {
        let mut s = format!(
            "error: a value is required for '{}' but none was supplied\n",
            display(a)
        );
        if !a.possible.is_empty() {
            let _ = writeln!(s, "  [possible values: {}]", a.possible.join(", "));
        }
        s.push('\n');
        s.push_str(self.err_footer());
        s
    }

    fn duplicate(&self, a: &ArgDef) -> String {
        format!(
            "error: the argument '{}' cannot be used multiple times\n\n{}\n\n{}",
            display(a),
            self.usage_generic(),
            self.err_footer()
        )
    }

    /// Validates a value; returns an error message on failure.
    fn validate(&self, idx: usize, v: &str) -> Result<(), String> {
        let a = &ARGS[idx];
        match a.id {
            "columns" => {
                if v.is_empty() {
                    return Err(format!(
                        "error: invalid value '' for '{}': cannot parse integer from empty string\n\n{}",
                        display(a),
                        self.err_footer()
                    ));
                }
                let digits = v.strip_prefix('+').unwrap_or(v);
                if digits.is_empty() || !digits.bytes().all(|b| b.is_ascii_digit()) {
                    return Err(format!(
                        "error: invalid value '{}' for '{}': invalid digit found in string\n\n{}",
                        v,
                        display(a),
                        self.err_footer()
                    ));
                }
                if digits.parse::<u64>().is_err() {
                    return Err(format!(
                        "error: invalid value '{}' for '{}': number too large to fit in target type\n\n{}",
                        v,
                        display(a),
                        self.err_footer()
                    ));
                }
                Ok(())
            }
            "output" => {
                if v == "json" {
                    Ok(())
                } else if v == "yaml" || v == "cbor" {
                    Err(format!(
                        "error: invalid value '{v}' for '{}': This version of tokei was compiled without any '{v}' serialization support, to enable serialization, reinstall tokei with the features flag.\n\n    cargo install tokei --features {v}\n\nIf you want to enable all supported serialization formats, you can use the 'all' feature.\n\n    cargo install tokei --features all\n\n\n{}",
                        display(a),
                        self.err_footer()
                    ))
                } else {
                    Err(format!(
                        "error: invalid value '{}' for '{}': \"{}\" is not a supported serialization format\n\n{}",
                        v,
                        display(a),
                        v,
                        self.err_footer()
                    ))
                }
            }
            _ if !a.possible.is_empty() => {
                let ignore_case = a.id != "num_format_style";
                let ok = a.possible.iter().any(|p| {
                    if ignore_case {
                        p.eq_ignore_ascii_case(v)
                    } else {
                        *p == v
                    }
                });
                if ok {
                    return Ok(());
                }
                if v.is_empty() {
                    return Err(self.missing_value(a));
                }
                let mut s = format!("error: invalid value '{}' for '{}'\n", v, display(a));
                let _ = writeln!(s, "  [possible values: {}]", a.possible.join(", "));
                s.push('\n');
                if let Some(sug) = did_you_mean(v, a.possible.iter().copied()) {
                    let _ = write!(s, "  tip: a similar value exists: '{}'\n\n", sug);
                }
                s.push_str(self.err_footer());
                Err(s)
            }
            _ => Ok(()),
        }
    }

    fn resolve(&mut self, p: &mut Pending) -> Result<(), String> {
        match std::mem::replace(p, Pending::None) {
            Pending::None => Ok(()),
            Pending::Wanting(i) => Err(self.missing_value(&ARGS[i])),
            Pending::Have(i, v) => {
                self.validate(i, &v)?;
                self.values[i].push(v);
                Ok(())
            }
        }
    }

    /// Registers an occurrence of an argument (duplicate checking).
    fn occur(&mut self, i: usize) -> Result<(), String> {
        if self.counts[i] > 0 && !ARGS[i].multiple {
            return Err(self.duplicate(&ARGS[i]));
        }
        if self.counts[i] == 0 {
            self.seen.push(i);
        }
        self.counts[i] += 1;
        Ok(())
    }
}

pub fn parse(args: &[String]) -> Outcome {
    let bin = args
        .first()
        .map(|a| {
            std::path::Path::new(a)
                .file_name()
                .map(|f| f.to_string_lossy().to_string())
                .unwrap_or_else(|| a.clone())
        })
        .unwrap_or_else(|| "tokei".to_string());
    let mut p = Parser {
        bin,
        seen: Vec::new(),
        counts: vec![0; ARGS.len()],
        values: vec![Vec::new(); ARGS.len()],
        input: Vec::new(),
    };
    let mut pending = Pending::None;
    let mut trailing = false;
    let mut idx = 1;
    macro_rules! tryo {
        ($e:expr) => {
            match $e {
                Ok(v) => v,
                Err(e) => return Outcome::Error(e),
            }
        };
    }
    while idx < args.len() {
        let tok = args[idx].clone();
        idx += 1;
        if trailing {
            p.input.push(tok);
            continue;
        }
        if tok == "--" {
            tryo!(p.resolve(&mut pending));
            trailing = true;
            continue;
        }
        if let Some(rest) = tok.strip_prefix("--") {
            let (name, val) = match rest.find('=') {
                Some(i) => (&rest[..i], Some(rest[i + 1..].to_string())),
                None => (rest, None),
            };
            let ai = match ARGS.iter().position(|a| a.long == name) {
                Some(i) => i,
                None => {
                    let sug = did_you_mean(name, ARGS.iter().map(|a| a.long));
                    let sug = sug.and_then(|s| ARGS.iter().find(|a| a.long == s));
                    return Outcome::Error(p.unexpected(&format!("--{}", name), sug));
                }
            };
            tryo!(p.resolve(&mut pending));
            tryo!(p.occur(ai));
            let a = &ARGS[ai];
            match a.kind {
                Kind::Flag | Kind::Count => {
                    if let Some(v) = val {
                        return Outcome::Error(format!(
                            "error: unexpected value '{}' for '{}' found; no more were expected\n\nUsage: {} {} [input]...\n\n{}",
                            v,
                            display(a),
                            p.bin,
                            display(a),
                            p.err_footer()
                        ));
                    }
                    if a.id == "help" {
                        return Outcome::Help;
                    }
                    if a.id == "version" {
                        return Outcome::Version;
                    }
                }
                Kind::Opt => match val {
                    Some(v) => pending = Pending::Have(ai, v),
                    None => pending = Pending::Wanting(ai),
                },
            }
            continue;
        }
        if tok.starts_with('-') && tok.len() > 1 {
            // short flags
            let chars: Vec<char> = tok[1..].chars().collect();
            let mut ci = 0;
            while ci < chars.len() {
                let c = chars[ci];
                let ai = match ARGS.iter().position(|a| a.short == Some(c)) {
                    Some(i) => i,
                    None => {
                        return Outcome::Error(p.unexpected(&format!("-{}", c), None));
                    }
                };
                tryo!(p.resolve(&mut pending));
                tryo!(p.occur(ai));
                let a = &ARGS[ai];
                match a.kind {
                    Kind::Flag | Kind::Count => {
                        if a.id == "help" {
                            return Outcome::Help;
                        }
                        if a.id == "version" {
                            return Outcome::Version;
                        }
                        ci += 1;
                    }
                    Kind::Opt => {
                        let rest: String = chars[ci + 1..].iter().collect();
                        if rest.is_empty() {
                            pending = Pending::Wanting(ai);
                        } else {
                            let v = rest.strip_prefix('=').unwrap_or(&rest).to_string();
                            pending = Pending::Have(ai, v);
                        }
                        break;
                    }
                }
            }
            continue;
        }
        // a value
        match pending {
            Pending::Wanting(i) => {
                pending = Pending::Have(i, tok);
            }
            _ => {
                tryo!(p.resolve(&mut pending));
                p.input.push(tok);
            }
        }
    }
    tryo!(p.resolve(&mut pending));

    // Conflicts
    let conflicts: &[(&str, &str)] = &[
        ("output", "num_format_style"),
        ("num_format_style", "output"),
        ("sort", "rsort"),
        ("rsort", "sort"),
    ];
    for &i in &p.seen {
        let a = &ARGS[i];
        for (x, y) in conflicts {
            if a.id == *x {
                if let Some(j) = ARGS.iter().position(|b| b.id == *y) {
                    if p.counts[j] > 0 {
                        let mut usage: Vec<String> = Vec::new();
                        for &k in &p.seen {
                            if k == j {
                                continue;
                            }
                            usage.push(display(&ARGS[k]));
                        }
                        let tail = if p.input.is_empty() { "[input]..." } else { "<input>..." };
                        return Outcome::Error(format!(
                            "error: the argument '{}' cannot be used with '{}'\n\nUsage: {} {} {}\n\n{}",
                            display(a),
                            display(&ARGS[j]),
                            p.bin,
                            usage.join(" "),
                            tail,
                            p.err_footer()
                        ));
                    }
                }
            }
        }
    }

    let get = |id: &str| -> &Vec<String> {
        let i = ARGS.iter().position(|a| a.id == id).unwrap();
        &p.values[i]
    };
    let cnt = |id: &str| -> usize {
        let i = ARGS.iter().position(|a| a.id == id).unwrap();
        p.counts[i]
    };
    let mut cli = Cli::default();
    cli.columns = get("columns").first().map(|v| v.strip_prefix('+').unwrap_or(v).parse().unwrap_or(0));
    cli.excluded = get("exclude").clone();
    cli.files = cnt("files") > 0;
    cli.file_input = get("file_input").first().cloned();
    cli.hidden = cnt("hidden") > 0;
    cli.languages = cnt("languages") > 0;
    cli.no_ignore = cnt("no_ignore") > 0;
    cli.no_ignore_parent = cnt("no_ignore_parent") > 0;
    cli.no_ignore_dot = cnt("no_ignore_dot") > 0;
    cli.no_ignore_vcs = cnt("no_ignore_vcs") > 0;
    cli.output = get("output").first().cloned();
    cli.streaming = get("streaming").first().map(|v| {
        if v.eq_ignore_ascii_case("json") {
            Streaming::Json
        } else {
            Streaming::Simple
        }
    });
    cli.sort = get("sort").first().and_then(|v| Sort::from_str_ci(v));
    cli.rsort = get("rsort").first().and_then(|v| Sort::from_str_ci(v));
    let types = get("types");
    if !types.is_empty() {
        let mut t = Vec::new();
        for v in types {
            for x in v.split(',') {
                t.push(x.to_string());
            }
        }
        cli.types = Some(t);
    }
    cli.compact = cnt("compact") > 0;
    cli.num_format = get("num_format_style").first().map(|v| match v.as_str() {
        "commas" => NumFormat::Commas,
        "dots" => NumFormat::Dots,
        "underscores" => NumFormat::Underscores,
        _ => NumFormat::Plain,
    });
    cli.verbose = cnt("verbose") as u64;
    cli.input = p.input.clone();
    Outcome::Run(cli)
}

pub fn help_text(bin: &str) -> String {
    let mut s = String::new();
    s.push_str("Count your code, quickly.\nSupport this project on GitHub Sponsors: https://github.com/sponsors/XAMPPRocky\n\n");
    let _ = writeln!(s, "Usage: {} [OPTIONS] [input]...\n", bin);
    s.push_str(HELP_BODY);
    s
}

const HELP_BODY: &str = "Arguments:
  [input]...  The path(s) to the file or directory to be counted. (default current directory)

Options:
  -c, --columns <columns>              Sets a strict column width of the output, only available for
                                       terminal output.
  -e, --exclude <exclude>              Ignore all files & directories matching the pattern.
  -f, --files                          Will print out statistics on individual files.
  -i, --input <file_input>             Gives statistics from a previous tokei run. Can be given a
                                       file path, or \"stdin\" to read from stdin.
      --hidden                         Count hidden files.
  -l, --languages                      Prints out supported languages and their extensions.
      --no-ignore                      Don't respect ignore files (.gitignore, .ignore, etc.). This
                                       implies --no-ignore-parent, --no-ignore-dot, and
                                       --no-ignore-vcs.
      --no-ignore-parent               Don't respect ignore files (.gitignore, .ignore, etc.) in
                                       parent directories.
      --no-ignore-dot                  Don't respect .ignore and .tokeignore files, including those
                                       in parent directories.
      --no-ignore-vcs                  Don't respect VCS ignore files (.gitignore, .hgignore, etc.)
                                       including those in parent directories.
  -o, --output <output>                Outputs Tokei in a specific format. Compile with additional
                                       features for more format support.
      --streaming <streaming>          prints the (language, path, lines, blanks, code, comments)
                                       records as simple lines or as Json for batch processing
                                       [possible values: simple, json]
  -s, --sort <sort>                    Sort languages based on column [possible values: files,
                                       lines, blanks, code, comments]
  -r, --rsort <rsort>                  Reverse sort languages based on column [possible values:
                                       files, lines, blanks, code, comments]
  -t, --types <types>                  Filters output by language type, separated by a comma. i.e.
                                       -t=Rust,Markdown
  -C, --compact                        Do not print statistics about embedded languages.
  -n, --num-format <num_format_style>  Format of printed numbers, i.e., plain (1234, default),
                                       commas (1,234), dots (1.234), or underscores (1_234). Cannot
                                       be used with --output. [possible values: commas, dots, plain,
                                       underscores]
  -v, --verbose...                     Set log output level:
                                                               1: to show unknown file extensions,
                                                               2: reserved for future debugging,
                                                               3: enable file level trace. Not
                                                               recommended on multiple files
  -h, --help                           Print help
  -V, --version                        Print version
";
EOF
echo ok"}

actions.command:
cd /workspace && cat > src/cli.rs <<'EOF'
//! Command line parsing, mimicking clap's behaviour and messages.

use std::fmt::Write as _;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Sort {
    Files,
    Lines,
    Blanks,
    Code,
    Comments,
}

impl Sort {
    pub fn from_str_ci(s: &str) -> Option<Sort> {
        match s.to_lowercase().as_str() {
            "files" => Some(Sort::Files),
            "lines" => Some(Sort::Lines),
            "blanks" => Some(Sort::Blanks),
            "code" => Some(Sort::Code),
            "comments" => Some(Sort::Comments),
            _ => None,
        }
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum NumFormat {
    Commas,
    Dots,
    Plain,
    Underscores,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Streaming {
    Simple,
    Json,
}

#[derive(Default, Debug)]
pub struct Cli {
    pub columns: Option<usize>,
    pub excluded: Vec<String>,
    pub files: bool,
    pub file_input: Option<String>,
    pub hidden: bool,
    pub languages: bool,
    pub no_ignore: bool,
    pub no_ignore_parent: bool,
    pub no_ignore_dot: bool,
    pub no_ignore_vcs: bool,
    pub output: Option<String>,
    pub streaming: Option<Streaming>,
    pub sort: Option<Sort>,
    pub rsort: Option<Sort>,
    pub types: Option<Vec<String>>,
    pub compact: bool,
    pub num_format: Option<NumFormat>,
    pub verbose: u64,
    pub input: Vec<String>,
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum Kind {
    Flag,
    Count,
    Opt,
}

struct ArgDef {
    id: &'static str,
    short: Option<char>,
    long: &'static str,
    kind: Kind,
    value_name: &'static str,
    multiple: bool,
    possible: &'static [&'static str],
}

const SORTS: &[&str] = &["files", "lines", "blanks", "code", "comments"];

static ARGS: &[ArgDef] = &[
    ArgDef { id: "columns", short: Some('c'), long: "columns", kind: Kind::Opt, value_name: "columns", multiple: false, possible: &[] },
    ArgDef { id: "exclude", short: Some('e'), long: "exclude", kind: Kind::Opt, value_name: "exclude", multiple: true, possible: &[] },
    ArgDef { id: "files", short: Some('f'), long: "files", kind: Kind::Flag, value_name: "", multiple: false, possible: &[] },
    ArgDef { id: "file_input", short: Some('i'), long: "input", kind: Kind::Opt, value_name: "file_input", multiple: false, possible: &[] },
    ArgDef { id: "hidden", short: None, long: "hidden", kind: Kind::Flag, value_name: "", multiple: false, possible: &[] },
    ArgDef { id: "languages", short: Some('l'), long: "languages", kind: Kind::Flag, value_name: "", multiple: false, possible: &[] },
    ArgDef { id: "no_ignore", short: None, long: "no-ignore", kind: Kind::Flag, value_name: "", multiple: false, possible: &[] },
    ArgDef { id: "no_ignore_parent", short: None, long: "no-ignore-parent", kind: Kind::Flag, value_name: "", multiple: false, possible: &[] },
    ArgDef { id: "no_ignore_dot", short: None, long: "no-ignore-dot", kind: Kind::Flag, value_name: "", multiple: false, possible: &[] },
    ArgDef { id: "no_ignore_vcs", short: None, long: "no-ignore-vcs", kind: Kind::Flag, value_name: "", multiple: false, possible: &[] },
    ArgDef { id: "output", short: Some('o'), long: "output", kind: Kind::Opt, value_name: "output", multiple: false, possible: &[] },
    ArgDef { id: "streaming", short: None, long: "streaming", kind: Kind::Opt, value_name: "streaming", multiple: false, possible: &["simple", "json"] },
    ArgDef { id: "sort", short: Some('s'), long: "sort", kind: Kind::Opt, value_name: "sort", multiple: false, possible: SORTS },
    ArgDef { id: "rsort", short: Some('r'), long: "rsort", kind: Kind::Opt, value_name: "rsort", multiple: false, possible: SORTS },
    ArgDef { id: "types", short: Some('t'), long: "types", kind: Kind::Opt, value_name: "types", multiple: true, possible: &[] },
    ArgDef { id: "compact", short: Some('C'), long: "compact", kind: Kind::Flag, value_name: "", multiple: false, possible: &[] },
    ArgDef { id: "num_format_style", short: Some('n'), long: "num-format", kind: Kind::Opt, value_name: "num_format_style", multiple: false, possible: &["commas", "dots", "plain", "underscores"] },
    ArgDef { id: "verbose", short: Some('v'), long: "verbose", kind: Kind::Count, value_name: "", multiple: true, possible: &[] },
    ArgDef { id: "help", short: Some('h'), long: "help", kind: Kind::Flag, value_name: "", multiple: false, possible: &[] },
    ArgDef { id: "version", short: Some('V'), long: "version", kind: Kind::Flag, value_name: "", multiple: false, possible: &[] },
];

pub const VERSION: &str = "tokei 14.0.0 compiled with serialization support: json";

pub enum Outcome {
    Run(Cli),
    Help,
    Version,
    Error(String),
}

fn display(a: &ArgDef) -> String {
    match a.kind {
        Kind::Opt => format!("--{} <{}>", a.long, a.value_name),
        _ => format!("--{}", a.long),
    }
}

pub fn jaro(a: &str, b: &str) -> f64 {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    let (al, bl) = (a.len(), b.len());
    if al == 0 && bl == 0 {
        return 1.0;
    }
    if al == 0 || bl == 0 {
        return 0.0;
    }
    let mut range = std::cmp::max(al, bl) / 2;
    range = range.saturating_sub(1);
    let mut af = vec![false; al];
    let mut bf = vec![false; bl];
    let mut matches = 0usize;
    for i in 0..al {
        let lo = if i > range { i - range } else { 0 };
        let hi = std::cmp::min(bl, i + range + 1);
        for j in 0..hi {
            if lo <= j && a[i] == b[j] && !bf[j] {
                af[i] = true;
                bf[j] = true;
                matches += 1;
                break;
            }
        }
    }
    if matches == 0 {
        return 0.0;
    }
    let mut trans = 0usize;
    let mut k = 0usize;
    for i in 0..al {
        if af[i] {
            while k < bl && !bf[k] {
                k += 1;
            }
            if k < bl {
                if a[i] != b[k] {
                    trans += 1;
                }
                k += 1;
            }
        }
    }
    trans /= 2;
    let m = matches as f64;
    (m / al as f64 + m / bl as f64 + (m - trans as f64) / m) / 3.0
}

fn did_you_mean<'a>(v: &str, cands: impl Iterator<Item = &'a str>) -> Option<String> {
    let mut c: Vec<(f64, String)> = cands
        .map(|p| (jaro(v, p), p.to_string()))
        .filter(|(conf, _)| *conf > 0.7)
        .collect();
    c.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap_or(std::cmp::Ordering::Equal));
    c.pop().map(|x| x.1)
}

struct Parser {
    bin: String,
    seen: Vec<usize>, // order of first occurrence of arg indexes
    counts: Vec<usize>,
    values: Vec<Vec<String>>,
    input: Vec<String>,
}

enum Pending {
    None,
    Wanting(usize),
    Have(usize, String),
}

impl Parser {
    fn usage_generic(&self) -> String {
        format!("Usage: {} [OPTIONS] [input]...", self.bin)
    }

    fn err_footer(&self) -> &'static str {
        "For more information, try '--help'.\n"
    }

    fn unexpected(&self, tok: &str, suggestion: Option<&ArgDef>) -> String {
        let mut s = format!("error: unexpected argument '{}' found\n\n", tok);
        match suggestion {
            Some(a) => {
                let _ = write!(s, "  tip: a similar argument exists: '--{}'\n\n", a.long);
                let _ = write!(s, "Usage: {} {} [input]...\n\n", self.bin, display(a));
            }
            None => {
                let _ = write!(s, "  tip: to pass '{}' as a value, use '-- {}'\n\n", tok, tok);
                let _ = write!(s, "{}\n\n", self.usage_generic());
            }
        }
        s.push_str(self.err_footer());
        s
    }

    fn missing_value(&self, a: &ArgDef) -> String {
        let mut s = format!(
            "error: a value is required for '{}' but none was supplied\n",
            display(a)
        );
        if !a.possible.is_empty() {
            let _ = writeln!(s, "  [possible values: {}]", a.possible.join(", "));
        }
        s.push('\n');
        s.push_str(self.err_footer());
        s
    }

    fn duplicate(&self, a: &ArgDef) -> String {
        format!(
            "error: the argument '{}' cannot be used multiple times\n\n{}\n\n{}",
            display(a),
            self.usage_generic(),
            self.err_footer()
        )
    }

    /// Validates a value; returns an error message on failure.
    fn validate(&self, idx: usize, v: &str) -> Result<(), String> {
        let a = &ARGS[idx];
        match a.id {
            "columns" => {
                if v.is_empty() {
                    return Err(format!(
                        "error: invalid value '' for '{}': cannot parse integer from empty string\n\n{}",
                        display(a),
                        self.err_footer()
                    ));
                }
                let digits = v.strip_prefix('+').unwrap_or(v);
                if digits.is_empty() || !digits.bytes().all(|b| b.is_ascii_digit()) {
                    return Err(format!(
                        "error: invalid value '{}' for '{}': invalid digit found in string\n\n{}",
                        v,
                        display(a),
                        self.err_footer()
                    ));
                }
                if digits.parse::<u64>().is_err() {
                    return Err(format!(
                        "error: invalid value '{}' for '{}': number too large to fit in target type\n\n{}",
                        v,
                        display(a),
                        self.err_footer()
                    ));
                }
                Ok(())
            }
            "output" => {
                if v == "json" {
                    Ok(())
                } else if v == "yaml" || v == "cbor" {
                    Err(format!(
                        "error: invalid value '{v}' for '{}': This version of tokei was compiled without any '{v}' serialization support, to enable serialization, reinstall tokei with the features flag.\n\n    cargo install tokei --features {v}\n\nIf you want to enable all supported serialization formats, you can use the 'all' feature.\n\n    cargo install tokei --features all\n\n\n{}",
                        display(a),
                        self.err_footer()
                    ))
                } else {
                    Err(format!(
                        "error: invalid value '{}' for '{}': \"{}\" is not a supported serialization format\n\n{}",
                        v,
                        display(a),
                        v,
                        self.err_footer()
                    ))
                }
            }
            _ if !a.possible.is_empty() => {
                let ignore_case = a.id != "num_format_style";
                let ok = a.possible.iter().any(|p| {
                    if ignore_case {
                        p.eq_ignore_ascii_case(v)
                    } else {
                        *p == v
                    }
                });
                if ok {
                    return Ok(());
                }
                if v.is_empty() {
                    return Err(self.missing_value(a));
                }
                let mut s = format!("error: invalid value '{}' for '{}'\n", v, display(a));
                let _ = writeln!(s, "  [possible values: {}]", a.possible.join(", "));
                s.push('\n');
                if let Some(sug) = did_you_mean(v, a.possible.iter().copied()) {
                    let _ = write!(s, "  tip: a similar value exists: '{}'\n\n", sug);
                }
                s.push_str(self.err_footer());
                Err(s)
            }
            _ => Ok(()),
        }
    }

    fn resolve(&mut self, p: &mut Pending) -> Result<(), String> {
        match std::mem::replace(p, Pending::None) {
            Pending::None => Ok(()),
            Pending::Wanting(i) => Err(self.missing_value(&ARGS[i])),
            Pending::Have(i, v) => {
                self.validate(i, &v)?;
                self.values[i].push(v);
                Ok(())
            }
        }
    }

    /// Registers an occurrence of an argument (duplicate checking).
    fn occur(&mut self, i: usize) -> Result<(), String> {
        if self.counts[i] > 0 && !ARGS[i].multiple {
            return Err(self.duplicate(&ARGS[i]));
        }
        if self.counts[i] == 0 {
            self.seen.push(i);
        }
        self.counts[i] += 1;
        Ok(())
    }
}

pub fn parse(args: &[String]) -> Outcome {
    let bin = args
        .first()
        .map(|a| {
            std::path::Path::new(a)
                .file_name()
                .map(|f| f.to_string_lossy().to_string())
                .unwrap_or_else(|| a.clone())
        })
        .unwrap_or_else(|| "tokei".to_string());
    let mut p = Parser {
        bin,
        seen: Vec::new(),
        counts: vec![0; ARGS.len()],
        values: vec![Vec::new(); ARGS.len()],
        input: Vec::new(),
    };
    let mut pending = Pending::None;
    let mut trailing = false;
    let mut idx = 1;
    macro_rules! tryo {
        ($e:expr) => {
            match $e {
                Ok(v) => v,
                Err(e) => return Outcome::Error(e),
            }
        };
    }
    while idx < args.len() {
        let tok = args[idx].clone();
        idx += 1;
        if trailing {
            p.input.push(tok);
            continue;
        }
        if tok == "--" {
            tryo!(p.resolve(&mut pending));
            trailing = true;
            continue;
        }
        if let Some(rest) = tok.strip_prefix("--") {
            let (name, val) = match rest.find('=') {
                Some(i) => (&rest[..i], Some(rest[i + 1..].to_string())),
                None => (rest, None),
            };
            let ai = match ARGS.iter().position(|a| a.long == name) {
                Some(i) => i,
                None => {
                    let sug = did_you_mean(name, ARGS.iter().map(|a| a.long));
                    let sug = sug.and_then(|s| ARGS.iter().find(|a| a.long == s));
                    return Outcome::Error(p.unexpected(&format!("--{}", name), sug));
                }
            };
            tryo!(p.resolve(&mut pending));
            tryo!(p.occur(ai));
            let a = &ARGS[ai];
            match a.kind {
                Kind::Flag | Kind::Count => {
                    if let Some(v) = val {
                        return Outcome::Error(format!(
                            "error: unexpected value '{}' for '{}' found; no more were expected\n\nUsage: {} {} [input]...\n\n{}",
                            v,
                            display(a),
                            p.bin,
                            display(a),
                            p.err_footer()
                        ));
                    }
                    if a.id == "help" {
                        return Outcome::Help;
                    }
                    if a.id == "version" {
                        return Outcome::Version;
                    }
                }
                Kind::Opt => match val {
                    Some(v) => pending = Pending::Have(ai, v),
                    None => pending = Pending::Wanting(ai),
                },
            }
            continue;
        }
        if tok.starts_with('-') && tok.len() > 1 {
            // short flags
            let chars: Vec<char> = tok[1..].chars().collect();
            let mut ci = 0;
            while ci < chars.len() {
                let c = chars[ci];
                let ai = match ARGS.iter().position(|a| a.short == Some(c)) {
                    Some(i) => i,
                    None => {
                        return Outcome::Error(p.unexpected(&format!("-{}", c), None));
                    }
                };
                tryo!(p.resolve(&mut pending));
                tryo!(p.occur(ai));
                let a = &ARGS[ai];
                match a.kind {
                    Kind::Flag | Kind::Count => {
                        if a.id == "help" {
                            return Outcome::Help;
                        }
                        if a.id == "version" {
                            return Outcome::Version;
                        }
                        ci += 1;
                    }
                    Kind::Opt => {
                        let rest: String = chars[ci + 1..].iter().collect();
                        if rest.is_empty() {
                            pending = Pending::Wanting(ai);
                        } else {
                            let v = rest.strip_prefix('=').unwrap_or(&rest).to_string();
                            pending = Pending::Have(ai, v);
                        }
                        break;
                    }
                }
            }
            continue;
        }
        // a value
        match pending {
            Pending::Wanting(i) => {
                pending = Pending::Have(i, tok);
            }
            _ => {
                tryo!(p.resolve(&mut pending));
                p.input.push(tok);
            }
        }
    }
    tryo!(p.resolve(&mut pending));

    // Conflicts
    let conflicts: &[(&str, &str)] = &[
        ("output", "num_format_style"),
        ("num_format_style", "output"),
        ("sort", "rsort"),
        ("rsort", "sort"),
    ];
    for &i in &p.seen {
        let a = &ARGS[i];
        for (x, y) in conflicts {
            if a.id == *x {
                if let Some(j) = ARGS.iter().position(|b| b.id == *y) {
                    if p.counts[j] > 0 {
                        let mut usage: Vec<String> = Vec::new();
                        for &k in &p.seen {
                            if k == j {
                                continue;
                            }
                            usage.push(display(&ARGS[k]));
                        }
                        let tail = if p.input.is_empty() { "[input]..." } else { "<input>..." };
                        return Outcome::Error(format!(
                            "error: the argument '{}' cannot be used with '{}'\n\nUsage: {} {} {}\n\n{}",
                            display(a),
                            display(&ARGS[j]),
                            p.bin,
                            usage.join(" "),
                            tail,
                            p.err_footer()
                        ));
                    }
                }
            }
        }
    }

    let get = |id: &str| -> &Vec<String> {
        let i = ARGS.iter().position(|a| a.id == id).unwrap();
        &p.values[i]
    };
    let cnt = |id: &str| -> usize {
        let i = ARGS.iter().position(|a| a.id == id).unwrap();
        p.counts[i]
    };
    let mut cli = Cli::default();
    cli.columns = get("columns").first().map(|v| v.strip_prefix('+').unwrap_or(v).parse().unwrap_or(0));
    cli.excluded = get("exclude").clone();
    cli.files = cnt("files") > 0;
    cli.file_input = get("file_input").first().cloned();
    cli.hidden = cnt("hidden") > 0;
    cli.languages = cnt("languages") > 0;
    cli.no_ignore = cnt("no_ignore") > 0;
    cli.no_ignore_parent = cnt("no_ignore_parent") > 0;
    cli.no_ignore_dot = cnt("no_ignore_dot") > 0;
    cli.no_ignore_vcs = cnt("no_ignore_vcs") > 0;
    cli.output = get("output").first().cloned();
    cli.streaming = get("streaming").first().map(|v| {
        if v.eq_ignore_ascii_case("json") {
            Streaming::Json
        } else {
            Streaming::Simple
        }
    });
    cli.sort = get("sort").first().and_then(|v| Sort::from_str_ci(v));
    cli.rsort = get("rsort").first().and_then(|v| Sort::from_str_ci(v));
    let types = get("types");
    if !types.is_empty() {
        let mut t = Vec::new();
        for v in types {
            for x in v.split(',') {
                t.push(x.to_string());
            }
        }
        cli.types = Some(t);
    }
    cli.compact = cnt("compact") > 0;
    cli.num_format = get("num_format_style").first().map(|v| match v.as_str() {
        "commas" => NumFormat::Commas,
        "dots" => NumFormat::Dots,
        "underscores" => NumFormat::Underscores,
        _ => NumFormat::Plain,
    });
    cli.verbose = cnt("verbose") as u64;
    cli.input = p.input.clone();
    Outcome::Run(cli)
}

pub fn help_text(bin: &str) -> String {
    let mut s = String::new();
    s.push_str("Count your code, quickly.\nSupport this project on GitHub Sponsors: https://github.com/sponsors/XAMPPRocky\n\n");
    let _ = writeln!(s, "Usage: {} [OPTIONS] [input]...\n", bin);
    s.push_str(HELP_BODY);
    s
}

const HELP_BODY: &str = "Arguments:
  [input]...  The path(s) to the file or directory to be counted. (default current directory)

Options:
  -c, --columns <columns>              Sets a strict column width of the output, only available for
                                       terminal output.
  -e, --exclude <exclude>              Ignore all files & directories matching the pattern.
  -f, --files                          Will print out statistics on individual files.
  -i, --input <file_input>             Gives statistics from a previous tokei run. Can be given a
                                       file path, or \"stdin\" to read from stdin.
      --hidden                         Count hidden files.
  -l, --languages                      Prints out supported languages and their extensions.
      --no-ignore                      Don't respect ignore files (.gitignore, .ignore, etc.). This
                                       implies --no-ignore-parent, --no-ignore-dot, and
                                       --no-ignore-vcs.
      --no-ignore-parent               Don't respect ignore files (.gitignore, .ignore, etc.) in
                                       parent directories.
      --no-ignore-dot                  Don't respect .ignore and .tokeignore files, including those
                                       in parent directories.
      --no-ignore-vcs                  Don't respect VCS ignore files (.gitignore, .hgignore, etc.)
                                       including those in parent directories.
  -o, --output <output>                Outputs Tokei in a specific format. Compile with additional
                                       features for more format support.
      --streaming <streaming>          prints the (language, path, lines, blanks, code, comments)
                                       records as simple lines or as Json for batch processing
                                       [possible values: simple, json]
  -s, --sort <sort>                    Sort languages based on column [possible values: files,
                                       lines, blanks, code, comments]
  -r, --rsort <rsort>                  Reverse sort languages based on column [possible values:
                                       files, lines, blanks, code, comments]
  -t, --types <types>                  Filters output by language type, separated by a comma. i.e.
                                       -t=Rust,Markdown
  -C, --compact                        Do not print statistics about embedded languages.
  -n, --num-format <num_format_style>  Format of printed numbers, i.e., plain (1234, default),
                                       commas (1,234), dots (1.234), or underscores (1_234). Cannot
                                       be used with --output. [possible values: commas, dots, plain,
                                       underscores]
  -v, --verbose...                     Set log output level:
                                                               1: to show unknown file extensions,
                                                               2: reserved for future debugging,
                                                               3: enable file level trace. Not
                                                               recommended on multiple files
  -h, --help                           Print help
  -V, --version                        Print version
";
EOF
echo ok

