{"command":"cd /workspace && cat > src/output.rs <<'EOF'
//! Output formatting.

use crate::cli::NumFormat;
use crate::lang::{self, LangId};
use crate::stats::{CodeStats, Language, Report};
use std::io::Write;

pub const ROW_CHAR: &str = "━";
pub const SUBROW_CHAR: &str = "─";

pub struct Printer<W: Write> {
    pub w: W,
    pub columns: usize,
    pub list_files: bool,
    pub color: bool,
    pub num: NumFormat,
}

pub fn fmt_num(n: usize, f: NumFormat) -> String {
    let s = n.to_string();
    let sep = match f {
        NumFormat::Plain => return s,
        NumFormat::Commas => ',',
        NumFormat::Dots => '.',
        NumFormat::Underscores => '_',
    };
    let bytes: Vec<char> = s.chars().collect();
    let mut out = String::new();
    let len = bytes.len();
    for (i, c) in bytes.iter().enumerate() {
        if i > 0 && (len - i) % 3 == 0 {
            out.push(sep);
        }
        out.push(*c);
    }
    out
}

fn char_len(s: &str) -> usize {
    s.chars().count()
}

fn pad_right(s: &str, width: usize) -> String {
    let l = char_len(s);
    if l >= width {
        s.to_string()
    } else {
        let mut o = s.to_string();
        o.extend(std::iter::repeat(' ').take(width - l));
        o
    }
}

fn pad_left(s: &str, width: usize) -> String {
    let l = char_len(s);
    if l >= width {
        s.to_string()
    } else {
        let mut o: String = std::iter::repeat(' ').take(width - l).collect();
        o.push_str(s);
        o
    }
}

impl<W: Write> Printer<W> {
    fn bold_blue(&self, s: &str) -> String {
        if self.color {
            format!("\x1b[1;34m{}\x1b[0m", s)
        } else {
            s.to_string()
        }
    }
    fn bold_magenta(&self, s: &str) -> String {
        if self.color {
            format!("\x1b[1;35m{}\x1b[0m", s)
        } else {
            s.to_string()
        }
    }
    fn blue(&self, s: &str) -> String {
        if self.color {
            format!("\x1b[34m{}\x1b[0m", s)
        } else {
            s.to_string()
        }
    }
    fn dimmed(&self, s: &str) -> String {
        if self.color {
            format!("\x1b[2m{}\x1b[0m", s)
        } else {
            s.to_string()
        }
    }

    pub fn print_row(&mut self) -> std::io::Result<()> {
        writeln!(self.w, "{}", ROW_CHAR.repeat(self.columns))
    }

    pub fn print_subrow(&mut self) -> std::io::Result<()> {
        let s = self.dimmed(&SUBROW_CHAR.repeat(self.columns));
        writeln!(self.w, "{}", s)
    }

    pub fn print_header(&mut self) -> std::io::Result<()> {
        self.print_row()?;
        let w = self.columns.saturating_sub(69);
        let line = format!(
            " {} {} {} {} {} {}",
            self.bold_blue(&pad_right("Language", w)),
            self.bold_blue(&pad_left("Files", 14)),
            self.bold_blue(&pad_left("Lines", 12)),
            self.bold_blue(&pad_left("Code", 12)),
            self.bold_blue(&pad_left("Comments", 12)),
            self.bold_blue(&pad_left("Blanks", 12)),
        );
        writeln!(self.w, "{}", line)?;
        self.print_row()
    }

    pub fn print_inaccuracy_warning(&mut self) -> std::io::Result<()> {
        writeln!(self.w, "Note: results can be inaccurate for languages marked with '(!)'")
    }

    fn language_name(&self, inaccurate: bool, name: &str, prefix: Option<&str>) -> String {
        let mut len = self
            .columns
            .saturating_sub(63)
            .saturating_sub(prefix.map_or(0, |p| p.len()));
        if inaccurate {
            len = len.saturating_sub(3);
        }
        let mut out = String::new();
        if let Some(p) = prefix {
            out.push_str(p);
        }
        if len < char_len(name) {
            let t: String = name.chars().take(len.saturating_sub(1)).collect();
            out.push(' ');
            out.push_str(&t);
            out.push('|');
        } else {
            out.push(' ');
            out.push_str(&self.bold_magenta(&pad_right(name, len)));
        }
        if inaccurate {
            out.push_str("(!)");
        }
        out
    }

    fn n(&self, x: usize) -> String {
        fmt_num(x, self.num)
    }

    pub fn print_language(&mut self, l: &Language, name: &str) -> std::io::Result<()> {
        let mut s = self.language_name(l.inaccurate, name, None);
        s.push_str(&format!(
            " {} {} {} {} {}",
            pad_left(&self.n(l.reports.len()), 8),
            pad_left(&self.n(l.lines()), 12),
            pad_left(&self.n(l.code), 12),
            pad_left(&self.n(l.comments), 12),
            pad_left(&self.n(l.blanks), 12)
        ));
        writeln!(self.w, "{}", s)
    }

    pub fn print_total_row(&mut self, files: usize, st: &CodeStats, inaccurate: bool) -> std::io::Result<()> {
        let mut s = self.language_name(inaccurate, "Total", None);
        let cols = [
            pad_left(&self.n(files), 8),
            pad_left(&self.n(st.lines()), 12),
            pad_left(&self.n(st.code), 12),
            pad_left(&self.n(st.comments), 12),
            pad_left(&self.n(st.blanks), 12),
        ];
        for c in cols.iter() {
            s.push(' ');
            s.push_str(&self.blue(c));
        }
        writeln!(self.w, "{}", s)
    }

    fn print_language_total(&mut self, parent: &Language) -> std::io::Result<()> {
        for (lid, reports) in &parent.children {
            let mut st = CodeStats::new();
            for r in reports {
                let x = r.stats.summarise();
                st.blanks += x.blanks;
                st.code += x.code;
                st.comments += x.comments;
            }
            let mut s = self.language_name(false, lang::name(*lid), Some(" |-"));
            s.push_str(&format!(
                " {} {} {} {} {}",
                pad_left(&self.n(reports.len()), 8),
                pad_left(&self.n(st.lines()), 12),
                pad_left(&self.n(st.code), 12),
                pad_left(&self.n(st.comments), 12),
                pad_left(&self.n(st.blanks), 12)
            ));
            writeln!(self.w, "{}", s)?;
        }
        let total = parent.summarise();
        let w = self.columns.saturating_sub(54);
        writeln!(
            self.w,
            " {} {} {} {} {}",
            pad_right("(Total)", w),
            pad_left(&self.n(total.lines()), 12),
            pad_left(&self.n(total.code), 12),
            pad_left(&self.n(total.comments), 12),
            pad_left(&self.n(total.blanks), 12)
        )
    }

    fn report_line(&self, name: &str, st: &CodeStats) -> String {
        let w = self.columns.saturating_sub(54);
        let name = if char_len(name) > w {
            let skip = char_len(name) - (w.saturating_sub(1));
            let tail: String = name.chars().skip(skip).collect();
            format!("|{}", tail)
        } else {
            name.to_string()
        };
        format!(
            " {} {:>12} {:>12} {:>12} {:>12}",
            pad_right(&name, w),
            st.lines(),
            st.code,
            st.comments,
            st.blanks
        )
    }

    fn print_report(&mut self, r: &Report) -> std::io::Result<()> {
        let s = self.report_line(&r.name, &r.stats);
        writeln!(self.w, "{}", s)
    }

    fn print_blob_row(&mut self, lid: LangId, st: &CodeStats) -> std::io::Result<()> {
        let mut s = self.language_name(false, lang::name(lid), Some(" |-"));
        let w = self.columns.saturating_sub(63).saturating_sub(3);
        // position so that the lines column ends at the same place as reports
        let lines_w = (self.columns.saturating_sub(40)).saturating_sub(4 + w);
        s.push_str(&format!(
            "{} {:>12} {:>12} {:>12}",
            pad_left(&st.lines().to_string(), lines_w),
            st.code,
            st.comments,
            st.blanks
        ));
        writeln!(self.w, "{}", s)
    }

    pub fn print_results(
        &mut self,
        languages: &[(LangId, &Language)],
        compact: bool,
        is_sorted: bool,
    ) -> std::io::Result<()> {
        let nonempty: Vec<&(LangId, &Language)> = languages.iter().filter(|(_, l)| !l.is_empty()).collect();
        let a: Vec<&(LangId, &Language)> = nonempty
            .iter()
            .filter(|(_, l)| compact || l.children.is_empty())
            .copied()
            .collect();
        let b: Vec<&(LangId, &Language)> = nonempty
            .iter()
            .filter(|(_, l)| !(compact || l.children.is_empty()))
            .copied()
            .collect();
        let mut first = true;
        for group in [&a, &b] {
            for (lid, language) in group.iter().map(|x| (x.0, x.1)) {
                let has_children = !(compact || language.children.is_empty());
                if first {
                    first = false;
                } else if has_children || self.list_files {
                    self.print_subrow()?;
                }
                self.print_language(language, lang::name(lid))?;
                if has_children {
                    self.print_language_total(language)?;
                }
                if self.list_files {
                    self.print_subrow()?;
                    let mut reports: Vec<&Report> = language.reports.iter().collect();
                    if !is_sorted {
                        reports.sort_by(|x, y| x.name.cmp(&y.name));
                    }
                    if compact {
                        for r in &reports {
                            self.print_report(r)?;
                        }
                    } else {
                        let ra: Vec<&Report> = reports.iter().filter(|r| r.stats.blobs.is_empty()).copied().collect();
                        let rb: Vec<&Report> = reports.iter().filter(|r| !r.stats.blobs.is_empty()).copied().collect();
                        for (gi, grp) in [&ra, &rb].iter().enumerate() {
                            let mut firstr = true;
                            for r in grp.iter() {
                                if gi == 0 {
                                    self.print_report(r)?;
                                } else {
                                    if firstr && ra.is_empty() {
                                        writeln!(self.w, " {}", r.name)?;
                                        firstr = false;
                                    } else {
                                        let dashes = self
                                            .columns
                                            .saturating_sub(4)
                                            .saturating_sub(r.name.len());
                                        writeln!(self.w, "-- {} {}", r.name, "-".repeat(dashes))?;
                                    }
                                    let mut own = r.stats.clone();
                                    own.blobs.clear();
                                    let s = self.report_line(&format!("|- {}", lang::name(lid)), &own);
                                    writeln!(self.w, "{}", s)?;
                                    for (bl, bs) in &r.stats.blobs {
                                        self.print_blob_row(*bl, bs)?;
                                    }
                                    let s = self.report_line(&r.name, &own);
                                    writeln!(self.w, "{}", s)?;
                                }
                            }
                        }
                    }
                }
            }
        }
        Ok(())
    }
}

pub fn print_languages_list(w: &mut dyn Write, color: bool) -> std::io::Result<()> {
    let b = |s: &str| -> String {
        if color {
            format!("\x1b[1m{}\x1b[0m", s)
        } else {
            s.to_string()
        }
    };
    let row = "━".repeat(72);
    writeln!(w, "{}", b(&row))?;
    writeln!(
        w,
        "{}{}{}{}",
        b("┃"),
        b(&pad_right(" Language", 35)),
        b(&pad_right("    Extensions", 35)),
        b("┃")
    )?;
    writeln!(w, "{}{}{}{}", b("┃"), b(&"━".repeat(35)), b(&"━".repeat(35)), b("┃"))?;
    for i in 0..lang::count() {
        let d = lang::def(i);
        let exts = if d.extensions.is_empty() {
            "<None>".to_string()
        } else {
            d.extensions.join(", ")
        };
        let exts = if char_len(&exts) > 30 {
            let t: String = exts.chars().take(27).collect();
            format!("{}...", t)
        } else {
            exts
        };
        writeln!(
            w,
            "{} {} {} {}",
            b("┃"),
            pad_right(d.name, 37),
            pad_right(&exts, 30),
            b("┃")
        )?;
    }
    writeln!(w, "{}", b(&row))?;
    writeln!(w)
}

// ---------------- JSON ----------------

pub fn stats_json(st: &CodeStats, out: &mut String) {
    out.push_str(&format!(
        "{{\"blanks\":{},\"code\":{},\"comments\":{},\"blobs\":{{",
        st.blanks, st.code, st.comments
    ));
    let mut first = true;
    for (k, v) in &st.blobs {
        if !first {
            out.push(',');
        }
        first = false;
        crate::json::escape(lang::name(*k), out);
        out.push(':');
        stats_json(v, out);
    }
    out.push_str("}}");
}

/// Streaming JSON uses sorted keys.
pub fn stats_json_sorted(st: &CodeStats, out: &mut String) {
    out.push_str("{\"blanks\":");
    out.push_str(&st.blanks.to_string());
    out.push_str(",\"blobs\":{");
    let mut first = true;
    let mut blobs: Vec<(&LangId, &CodeStats)> = st.blobs.iter().collect();
    blobs.sort_by(|a, b| lang::name(*a.0).cmp(lang::name(*b.0)));
    for (k, v) in blobs {
        if !first {
            out.push(',');
        }
        first = false;
        crate::json::escape(lang::name(*k), out);
        out.push(':');
        stats_json_sorted(v, out);
    }
    out.push_str(&format!("}},\"code\":{},\"comments\":{}}}", st.code, st.comments));
}

pub fn report_json(r: &Report, out: &mut String) {
    out.push_str("{\"stats\":");
    stats_json(&r.stats, out);
    out.push_str(",\"name\":");
    crate::json::escape(&r.name, out);
    out.push('}');
}

pub fn reports_json(rs: &[Report], out: &mut String) {
    out.push('[');
    for (i, r) in rs.iter().enumerate() {
        if i > 0 {
            out.push(',');
        }
        report_json(r, out);
    }
    out.push(']');
}

pub fn language_json(l: &Language, out: &mut String) {
    out.push_str(&format!(
        "{{\"blanks\":{},\"code\":{},\"comments\":{},\"reports\":",
        l.blanks, l.code, l.comments
    ));
    reports_json(&l.reports, out);
    out.push_str(",\"children\":{");
    let mut first = true;
    for (k, v) in &l.children {
        if !first {
            out.push(',');
        }
        first = false;
        crate::json::escape(lang::name(*k), out);
        out.push(':');
        reports_json(v, out);
    }
    out.push_str(&format!("}},\"inaccurate\":{}}}", l.inaccurate));
}
EOF
echo ok"}

