//! Configuration files (`tokei.toml` / `.tokeirc`).

use crate::cli::Sort;
use std::path::PathBuf;

#[derive(Default, Clone, Debug)]
pub struct Config {
    pub columns: Option<usize>,
    pub hidden: Option<bool>,
    pub no_ignore: Option<bool>,
    pub no_ignore_parent: Option<bool>,
    pub no_ignore_dot: Option<bool>,
    pub no_ignore_vcs: Option<bool>,
    pub treat_doc_strings_as_comments: Option<bool>,
    pub sort: Option<Sort>,
    pub types: Option<Vec<String>>,
}

#[derive(Debug, Clone)]
enum TVal {
    Bool(bool),
    Int(i64),
    Str(String),
    Arr(Vec<TVal>),
    Other,
}

fn parse_string(s: &str) -> Option<(String, &str)> {
    let mut chars = s.char_indices();
    let (_, q) = chars.next()?;
    if q == '"' {
        if s.starts_with("\"\"\"") {
            let rest = &s[3..];
            let end = rest.find("\"\"\"")?;
            let mut body = &rest[..end];
            if let Some(b) = body.strip_prefix('\n') {
                body = b;
            }
            return Some((body.to_string(), &rest[end + 3..]));
        }
        let mut out = String::new();
        let mut it = s[1..].char_indices();
        while let Some((i, c)) = it.next() {
            match c {
                '"' => return Some((out, &s[1 + i + 1..])),
                '\\' => {
                    let (_, e) = it.next()?;
                    match e {
                        'n' => out.push('\n'),
                        't' => out.push('\t'),
                        'r' => out.push('\r'),
                        '\\' => out.push('\\'),
                        '"' => out.push('"'),
                        'b' => out.push('\u{8}'),
                        'f' => out.push('\u{c}'),
                        'u' | 'U' => {
                            let n = if e == 'u' { 4 } else { 8 };
                            let mut h = String::new();
                            for _ in 0..n {
                                h.push(it.next()?.1);
                            }
                            out.push(char::from_u32(u32::from_str_radix(&h, 16).ok()?)?);
                        }
                        _ => return None,
                    }
                }
                '\n' => return None,
                c => out.push(c),
            }
        }
        None
    } else if q == '\'' {
        if s.starts_with("'''") {
            let rest = &s[3..];
            let end = rest.find("'''")?;
            let mut body = &rest[..end];
            if let Some(b) = body.strip_prefix('\n') {
                body = b;
            }
            return Some((body.to_string(), &rest[end + 3..]));
        }
        let rest = &s[1..];
        let end = rest.find('\'')?;
        if rest[..end].contains('\n') {
            return None;
        }
        Some((rest[..end].to_string(), &rest[end + 1..]))
    } else {
        None
    }
}

fn skip_ws_comments(mut s: &str) -> &str {
    loop {
        let t = s.trim_start_matches([' ', '\t', '\n', '\r']);
        if let Some(rest) = t.strip_prefix('#') {
            let nl = rest.find('\n').map_or(rest.len(), |i| i);
            s = &rest[nl..];
        } else {
            return t;
        }
    }
}

fn parse_value(s: &str) -> Option<(TVal, &str)> {
    let s = s.trim_start_matches([' ', '\t']);
    if s.starts_with('"') || s.starts_with('\'') {
        let (v, rest) = parse_string(s)?;
        return Some((TVal::Str(v), rest));
    }
    if let Some(rest) = s.strip_prefix('[') {
        let mut items = Vec::new();
        let mut r = skip_ws_comments(rest);
        loop {
            if let Some(rr) = r.strip_prefix(']') {
                return Some((TVal::Arr(items), rr));
            }
            let (v, rr) = parse_value(r)?;
            items.push(v);
            r = skip_ws_comments(rr);
            if let Some(rr) = r.strip_prefix(',') {
                r = skip_ws_comments(rr);
            } else if let Some(rr) = r.strip_prefix(']') {
                return Some((TVal::Arr(items), rr));
            } else {
                return None;
            }
        }
    }
    if let Some(rest) = s.strip_prefix('{') {
        // inline table: skip to matching brace (no nesting support beyond simple)
        let mut depth = 1;
        let mut i = 0;
        let b = rest.as_bytes();
        while i < b.len() {
            match b[i] {
                b'{' => depth += 1,
                b'}' => {
                    depth -= 1;
                    if depth == 0 {
                        return Some((TVal::Other, &rest[i + 1..]));
                    }
                }
                _ => {}
            }
            i += 1;
        }
        return None;
    }
    let end = s
        .find(|c: char| c == ',' || c == ']' || c == '\n' || c == '#' || c == '}')
        .unwrap_or(s.len());
    let tok = s[..end].trim();
    let rest = &s[end..];
    match tok {
        "true" => Some((TVal::Bool(true), rest)),
        "false" => Some((TVal::Bool(false), rest)),
        _ => {
            let t = tok.replace('_', "");
            if let Ok(i) = t.parse::<i64>() {
                Some((TVal::Int(i), rest))
            } else if t.parse::<f64>().is_ok() || tok.contains('-') || tok.contains(':') {
                Some((TVal::Other, rest))
            } else {
                None
            }
        }
    }
}

fn parse_toml(text: &str) -> Option<Vec<(String, TVal)>> {
    let mut out = Vec::new();
    let mut s = text;
    let mut in_table = false;
    loop {
        s = skip_ws_comments(s);
        if s.is_empty() {
            break;
        }
        if s.starts_with('[') {
            let nl = s.find('\n').unwrap_or(s.len());
            let header = s[..nl].trim();
            if !header.ends_with(']') && !header.contains("] #") && !header.contains("]#") {
                return None;
            }
            in_table = true;
            s = &s[nl..];
            continue;
        }
        let eq = s.find('=')?;
        let key = s[..eq].trim();
        if key.is_empty() || key.contains('\n') {
            return None;
        }
        let key = key.trim_matches('"').to_string();
        let (v, rest) = parse_value(&s[eq + 1..])?;
        let rest = rest.trim_start_matches([' ', '\t']);
        let rest = if rest.starts_with('#') {
            &rest[rest.find('\n').unwrap_or(rest.len())..]
        } else {
            rest
        };
        if !(rest.is_empty() || rest.starts_with('\n') || rest.starts_with("\r\n")) {
            return None;
        }
        if !in_table {
            if out.iter().any(|(k, _): &(String, TVal)| *k == key) {
                return None;
            }
            out.push((key, v));
        }
        s = rest;
    }
    Some(out)
}

fn config_from_str(text: &str) -> Option<Config> {
    let kv = parse_toml(text)?;
    let mut c = Config::default();
    for (k, v) in kv {
        match k.as_str() {
            "columns" => match v {
                TVal::Int(i) if i >= 0 => c.columns = Some(i as usize),
                _ => return None,
            },
            "hidden" | "no_ignore" | "no_ignore_parent" | "no_ignore_dot" | "no_ignore_vcs"
            | "treat_doc_strings_as_comments" => {
                let b = match v {
                    TVal::Bool(b) => b,
                    _ => return None,
                };
                match k.as_str() {
                    "hidden" => c.hidden = Some(b),
                    "no_ignore" => c.no_ignore = Some(b),
                    "no_ignore_parent" => c.no_ignore_parent = Some(b),
                    "no_ignore_dot" => c.no_ignore_dot = Some(b),
                    "no_ignore_vcs" => c.no_ignore_vcs = Some(b),
                    _ => c.treat_doc_strings_as_comments = Some(b),
                }
            }
            "sort" => match v {
                TVal::Str(s) => c.sort = Some(Sort::from_str_ci(&s)?),
                _ => return None,
            },
            "types" => match v {
                TVal::Arr(a) => {
                    let mut t = Vec::new();
                    for x in a {
                        match x {
                            TVal::Str(s) => t.push(s),
                            _ => return None,
                        }
                    }
                    c.types = Some(t);
                }
                _ => return None,
            },
            _ => {}
        }
    }
    Some(c)
}

fn read_dir_config(dir: Option<PathBuf>) -> Config {
    let dir = match dir {
        Some(d) => d,
        None => return Config::default(),
    };
    for name in ["tokei.toml", ".tokeirc"] {
        if let Ok(text) = std::fs::read_to_string(dir.join(name)) {
            return config_from_str(&text).unwrap_or_default();
        }
    }
    Config::default()
}

fn config_dir() -> Option<PathBuf> {
    if let Some(x) = std::env::var_os("XDG_CONFIG_HOME") {
        let p = PathBuf::from(x);
        if p.is_absolute() {
            return Some(p);
        }
    }
    std::env::var_os("HOME").map(|h| PathBuf::from(h).join(".config"))
}

pub fn from_config_files() -> Config {
    let conf = read_dir_config(config_dir());
    let home = read_dir_config(std::env::var_os("HOME").map(PathBuf::from));
    let cur = read_dir_config(std::env::current_dir().ok());
    Config {
        columns: cur.columns.or(home.columns).or(conf.columns),
        hidden: cur.hidden.or(home.hidden).or(conf.hidden),
        no_ignore: cur.no_ignore.or(home.no_ignore).or(conf.no_ignore),
        no_ignore_parent: cur.no_ignore_parent.or(home.no_ignore_parent).or(conf.no_ignore_parent),
        no_ignore_dot: cur.no_ignore_dot.or(home.no_ignore_dot).or(conf.no_ignore_dot),
        no_ignore_vcs: cur.no_ignore_vcs.or(home.no_ignore_vcs).or(conf.no_ignore_vcs),
        treat_doc_strings_as_comments: cur
            .treat_doc_strings_as_comments
            .or(home.treat_doc_strings_as_comments)
            .or(conf.treat_doc_strings_as_comments),
        sort: cur.sort.or(home.sort).or(conf.sort),
        types: cur.types.or(home.types).or(conf.types),
    }
}
