//! Validation of `--input` files (previous tokei JSON output).

use crate::json::{self, Value};
use crate::lang;

fn is_uint(v: &Value) -> bool {
    matches!(v, Value::Number(_, true))
}

fn field<'a>(o: &'a [(String, Value)], name: &str) -> Option<&'a Value> {
    let mut found = None;
    for (k, v) in o {
        if k == name {
            if found.is_some() {
                return None;
            }
            found = Some(v);
        }
    }
    found
}

fn has_dup(o: &[(String, Value)]) -> bool {
    for (i, (k, _)) in o.iter().enumerate() {
        if o[..i].iter().any(|(k2, _)| k2 == k) {
            return true;
        }
    }
    false
}

fn is_lang_key(k: &str) -> bool {
    (0..lang::count()).any(|i| lang::name(i) == k) || crate::variants::VARIANTS.contains(&k)
}

fn check_stats(v: &Value) -> bool {
    let o = match v {
        Value::Object(o) => o,
        _ => return false,
    };
    if has_dup(o) {
        return false;
    }
    for f in ["blanks", "code", "comments"] {
        match field(o, f) {
            Some(x) if is_uint(x) => {}
            _ => return false,
        }
    }
    match field(o, "blobs") {
        Some(Value::Object(b)) => {
            if has_dup(b) {
                return false;
            }
            b.iter().all(|(k, v)| is_lang_key(k) && check_stats(v))
        }
        _ => false,
    }
}

fn check_report(v: &Value) -> bool {
    let o = match v {
        Value::Object(o) => o,
        _ => return false,
    };
    if has_dup(o) {
        return false;
    }
    match field(o, "stats") {
        Some(s) if check_stats(s) => {}
        _ => return false,
    }
    matches!(field(o, "name"), Some(Value::Str(_)))
}

fn check_reports(v: &Value) -> bool {
    match v {
        Value::Array(a) => a.iter().all(check_report),
        _ => false,
    }
}

fn check_language(v: &Value) -> bool {
    let o = match v {
        Value::Object(o) => o,
        _ => return false,
    };
    if has_dup(o) {
        return false;
    }
    for f in ["blanks", "code", "comments"] {
        match field(o, f) {
            Some(x) if is_uint(x) => {}
            _ => return false,
        }
    }
    match field(o, "reports") {
        Some(r) if check_reports(r) => {}
        _ => return false,
    }
    match field(o, "children") {
        Some(Value::Object(c)) => {
            if has_dup(c) {
                return false;
            }
            if !c.iter().all(|(k, v)| is_lang_key(k) && check_reports(v)) {
                return false;
            }
        }
        _ => return false,
    }
    matches!(field(o, "inaccurate"), Some(Value::Bool(_)))
}

/// Returns true when the given text is a valid language map.
pub fn validate(text: &[u8]) -> bool {
    let v = match json::parse(text) {
        Some(v) => v,
        None => return false,
    };
    let o = match &v {
        Value::Object(o) => o,
        _ => return false,
    };
    if has_dup(o) {
        return false;
    }
    let mut has_total = false;
    for (k, v) in o {
        if k == "Total" {
            has_total = true;
        } else if !is_lang_key(k) {
            return false;
        }
        if !check_language(v) {
            return false;
        }
    }
    has_total
}
