    fn ioctl(fd: i32, req: u64, ...) -> i32;
}

#[repr(C)]
struct WinSize {
    ws_row: u16,
    ws_col: u16,
    ws_xpixel: u16,
    ws_ypixel: u16,
}

fn stdout_is_tty() -> bool {
