}

fn term_width() -> Option<usize> {
    let mut ws = WinSize { ws_row: 0, ws_col: 0, ws_xpixel: 0, ws_ypixel: 0 };
    let r = unsafe { ioctl(1, 0x5413, &mut ws as *mut WinSize) };
    if r == -1 || ws.ws_col == 0 || ws.ws_row == 0 {
        None
    } else {
