    }
}

fn should_color() -> bool {
    fn norm(v: Option<std::ffi::OsString>) -> Option<bool> {
        v.map(|s| s != "0")
    }
    let force = norm(std::env::var_os("CLICOLOR_FORCE"));
    if force == Some(true) {
        return true;
    }
    if norm(std::env::var_os("NO_COLOR")).is_some() {
        return false;
    }
    norm(std::env::var_os("CLICOLOR")).unwrap_or(true) && stdout_is_tty()
}

fn timestamp() -> String {
    let secs = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_secs())
        .unwrap_or(0) as i64;
    let days = secs.div_euclid(86400);
    let rem = secs.rem_euclid(86400);
    let (h, m, s) = (rem / 3600, (rem % 3600) / 60, rem % 60);
    // civil from days (Howard Hinnant)
    let z = days + 719468;
    let era = z.div_euclid(146097);
    let doe = z - era * 146097;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let mo = if mp < 10 { mp + 3 } else { mp - 9 };
    let y = if mo <= 2 { y + 1 } else { y };
    format!("{:04}-{:02}-{:02}T{:02}:{:02}:{:02}Z", y, mo, d, h, m, s)
}

fn log(level: &str, target: &str, msg: &str) {
    let mut e = std::io::stderr();
    let _ = writeln!(e, "[{} {:<5} {}] {}", timestamp(), level, target, msg);
