        .types
        .clone()
        .map(|t| t.iter().filter_map(|x| lang::from_name(x)).collect())
        .or_else(|| {
            config
                .types
                .clone()
                .map(|t| t.iter().filter_map(|x| lang::from_name(x)).collect())
        });

    let wopts = walk::WalkOptions {
        hidden: cli.hidden || config.hidden.unwrap_or(false),
        no_ignore: cli.no_ignore || config.no_ignore.unwrap_or(false),
        no_ignore_parent: cli.no_ignore_parent || config.no_ignore_parent.unwrap_or(false),
        no_ignore_dot: cli.no_ignore_dot || config.no_ignore_dot.unwrap_or(false),
        no_ignore_vcs: cli.no_ignore_vcs || config.no_ignore_vcs.unwrap_or(false),
        excludes: cli.excluded.clone(),
    };
    let mut walker = walk::Walker::new(&wopts);
    let mut files: Vec<PathBuf> = Vec::new();
    for p in &inputs {
        let path = Path::new(p);
        let md = std::fs::metadata(path);
        let is_dir = md.as_ref().map(|m| m.is_dir()).unwrap_or(false);
        if is_dir {
            walker.files.clear();
            walker.walk_root(path, &mut |msg| log("ERROR", "tokei::utils::fs", &msg));
