                let mut s = String::from("{\"language\":");
                json::escape(lang::name(id), &mut s);
                s.push_str(",\"stats\":{\"name\":");
                json::escape(&report.name, &mut s);
                s.push_str(",\"stats\":");
                output::stats_json_sorted(&report.stats, &mut s);
                s.push_str("}}");
                let _ = writeln!(out, "{}", s);
            }
            None => {}
        }
        languages.entry(id).or_default().add_report(report);
