    if cli.streaming.is_some() {
        let _ = out.flush();
        return 0;
    }

    for l in languages.values_mut() {
        l.reports.sort_by(|a, b| path_cmp(&a.name, &b.name));
        for v in l.children.values_mut() {
            v.sort_by(|a, b| path_cmp(&a.name, &b.name));
        }
        l.total();
    }

    // Totals
    let mut total_stats = CodeStats::new();
    let mut total_files = 0;
    let mut any_inaccurate = false;
    for l in languages.values() {
        let s = l.summarise();
        total_stats.blanks += s.blanks;
        total_stats.code += s.code;
        total_stats.comments += s.comments;
        total_files += l.reports.len();
        any_inaccurate |= l.inaccurate;
    }

    if cli.output.is_some() {
        let mut s = String::from("{");
        for (id, l) in &languages {
            json::escape(lang::name(*id), &mut s);
            s.push(':');
            output::language_json(l, &mut s);
            s.push(',');
        }
        s.push_str("\"Total\":");
        s.push_str(&format!(
            "{{\"blanks\":{},\"code\":{},\"comments\":{},\"reports\":[],\"children\":{{",
            total_stats.blanks, total_stats.code, total_stats.comments
        ));
        let mut first = true;
        for (id, l) in &languages {
            if !first {
                s.push(',');
            }
            first = false;
            json::escape(lang::name(*id), &mut s);
            s.push(':');
            output::reports_json(&l.reports, &mut s);
        }
        s.push_str(&format!("}},\"inaccurate\":{}}}}}", any_inaccurate));
        let _ = write!(out, "{}", s);
        let _ = out.flush();
        return 0;
    }

    let mut columns = cli.columns.or(config.columns).or_else(|| {
        if cli.files {
            term_width()
        } else {
            None
        }
    });
    if let Some(c) = columns {
        if c < FALLBACK_ROW_LEN {
            columns = Some(FALLBACK_ROW_LEN);
        }
    }
    let columns = columns.unwrap_or(FALLBACK_ROW_LEN);

    let mut printer = output::Printer {
        w: out,
        columns,
        list_files: cli.files,
        color,
        num: cli.num_format.unwrap_or(NumFormat::Plain),
    };

    if any_inaccurate {
        let _ = printer.print_inaccuracy_warning();
    }
    let _ = printer.print_header();

    let sort = cli.sort.or(cli.rsort).or(config.sort);
    let reverse = cli.rsort.is_some();
    let mut list: Vec<(LangId, Language)> = languages.into_iter().collect();
    let is_sorted = if let Some(s) = sort {
        for (_, l) in list.iter_mut() {
            sort_reports(&mut l.reports, s);
        }
        list.sort_by(|a, b| sort_key(&b.1, s).cmp(&sort_key(&a.1, s)));
        if reverse {
            list.reverse();
        }
        true
    } else {
        false
    };
    let refs: Vec<(LangId, &Language)> = list.iter().map(|(i, l)| (*i, l)).collect();
    let _ = printer.print_results(&refs, cli.compact, is_sorted);
    let _ = printer.print_row();
    let _ = printer.print_total_row(total_files, &total_stats, any_inaccurate);
    let _ = printer.print_row();
    let _ = printer.w.flush();
    0
}

fn main() {
    let code = run();
    std::process::exit(code);
}
