fn decode(bytes: Vec<u8>) -> Vec<u8> {
    if bytes.starts_with(&[0xEF, 0xBB, 0xBF]) {
        return bytes[3..].to_vec();
    }
    let le = bytes.starts_with(&[0xFF, 0xFE]);
    let be = bytes.starts_with(&[0xFE, 0xFF]);
    if le || be {
        let body = &bytes[2..];
        let mut units = Vec::with_capacity(body.len() / 2);
        let mut i = 0;
        while i + 1 < body.len() {
            let u = if le {
