        while j < text.len() && is_ws(text[j]) {
            j += 1;
        }
        if j == ws_start {
            continue;
        }
        // \\s+ is greedy but may give back characters; the word must start
        // after the whitespace run.
        let ws = j;
        while j < text.len() && is_word(text[j]) {
            j += 1;
        }
        if j == ws {
            continue;
        }
        let word_end = j;
        // \\s*($|;|\\{)
        let mut k = word_end;
        let mut ok = false;
        loop {
            if k >= text.len() || text[k] == b'\\n' || text[k] == b';' || text[k] == b'{' {
