import os, subprocess, shutil, re, sys, json, tempfile
ORIG='/workspace/executable'; MINE='/tmp/bin/executable'
ENV=dict(os.environ, RAYON_NUM_THREADS='4')
TS=re.compile(r'\[\d{4}-\d\d-\d\dT\d\d:\d\d:\d\dZ ')
def build(files, root):
    for p,c in files.items():
        fp=os.path.join(root,p)
        os.makedirs(os.path.dirname(fp),exist_ok=True)
        if c is None: os.makedirs(fp,exist_ok=True); continue
        if isinstance(c,str): c=c.encode()
        open(fp,'wb').write(c)
def run(exe, args, cwd, stdin=None, env=None):
    e=dict(ENV); 
    if env: e.update(env)
    r=subprocess.run([exe]+args,cwd=cwd,capture_output=True,input=stdin,env=e)
    return r.returncode, r.stdout, TS.sub('[TS ',r.stderr.decode('utf-8','replace')).encode()
def compare(files, argsets, setup=None, stdin=None, env=None, show=True, name_exe='executable'):
    root=tempfile.mkdtemp(prefix='sc',dir='/tmp/sc')
    build(files, root)
    if setup: setup(root)
    bad=0
    # link both executables under the same name so usage strings match
    for args in argsets:
        a=run(ORIG,args,root,stdin,env); b=run(MINE,args,root,stdin,env)
        if a!=b:
            bad+=1
            if show:
                print('=== DIFF args',args)
                for k,(x,y) in enumerate(zip(a,b)):
                    if x!=y:
                        print(' part',['rc','stdout','stderr'][k])
                        if k==0: print('  orig',x,'mine',y)
                        else:
                            xs=x.decode('utf-8','replace').split('\n'); ys=y.decode('utf-8','replace').split('\n')
                            import difflib
                            for l in list(difflib.unified_diff(xs,ys,'orig','mine',lineterm='',n=1))[:40]: print('  ',l)
    shutil.rmtree(root)
    return bad
