    }
    fn parse(mut self) -> Result<Vec<Tok>, GlobError> {
        while let Some(c) = self.bump() {
            match c {
                '?' => self.push(Tok::Any),
                '*' => self.parse_star(),
                '[' => self.parse_class()?,
                '{' => {
                    if self.stack.len() > 1 {
                        return Err(GlobError::NestedAlternates);
                    }
                    self.stack.push(Vec::new());
                }
                '}' => {
                    let mut alts = Vec::new();
                    while self.stack.len() >= 2 {
                        alts.push(self.stack.pop().unwrap());
                    }
                    alts.reverse();
                    self.push(Tok::Alt(alts));
                }
                ',' => {
                    if self.stack.len() <= 1 {
                        self.push(Tok::Lit(','));
                    } else {
                        self.stack.push(Vec::new());
                    }
