                '\\' => match self.bump() {
                    None => return Err(GlobError::DanglingEscape),
                    Some(c) => self.push(Tok::Lit(c)),
                },
                c => self.push(Tok::Lit(c)),
            }
        }
        if self.stack.len() > 1 {
            return Err(GlobError::UnclosedAlternates);
        }
        Ok(self.stack.pop().unwrap())
    }
