        let prev = self.prev;
        if self.peek() != Some('*') {
            self.push(Tok::ZeroOrMore);
            return;
        }
        self.bump();
        if !self.have_tokens() {
            if !self.peek().map_or(true, is_sep) {
                self.push(Tok::ZeroOrMore);
                self.push(Tok::ZeroOrMore);
            } else {
                self.push(Tok::RecPrefix);
                self.bump();
            }
            return;
