impl Glob {
    pub fn parse(pat: &str) -> Result<Glob, GlobError> {
        let p = GParser { chars: pat.chars().collect(), pos: 0, prev: None, cur: None, stack: vec![Vec::new()] };
        let toks = p.parse()?;
        let match_all = toks.len() == 1 && toks[0] == Tok::RecPrefix;
        Ok(Glob { toks, match_all })
    }

    pub fn new(pat: &str) -> Option<Glob> {
        Glob::parse(pat).ok()
    }

    pub fn is_match(&self, path: &[u8]) -> bool {
        if self.match_all {
            return true;
        }
        let s: Vec<char> = String::from_utf8_lossy(path).chars().collect();
        match_toks(&self.toks, 0, &s)
    }
}

fn match_toks(toks: &[Tok], idx: usize, s: &[char]) -> bool {
    if toks.is_empty() {
        return s.is_empty();
    }
    let rest = &toks[1..];
    match &toks[0] {
        Tok::Lit(c) => !s.is_empty() && s[0] == *c && match_toks(rest, idx + 1, &s[1..]),
        Tok::Any => !s.is_empty() && s[0] != '/' && match_toks(rest, idx + 1, &s[1..]),
        Tok::Class { neg, ranges } => {
            if s.is_empty() {
                return false;
            }
            let c = s[0];
            let inside = ranges.iter().any(|(a, b)| c >= *a && c <= *b);
            if inside == *neg {
                return false;
            }
            match_toks(rest, idx + 1, &s[1..])
        }
        Tok::ZeroOrMore => {
            let mut k = 0;
            loop {
                if match_toks(rest, idx + 1, &s[k..]) {
                    return true;
                }
                if k >= s.len() || s[k] == '/' {
                    return false;
                }
                k += 1;
            }
        }
        Tok::RecPrefix => {
            if idx == 0 {
                // (?:/?|.*/)
                if match_toks(rest, idx + 1, s) {
                    return true;
                }
                for k in 0..s.len() {
                    if s[k] == '/' && match_toks(rest, idx + 1, &s[k + 1..]) {
                        return true;
                    }
                }
                false
            } else {
                rec_zero_or_more(rest, idx, s)
            }
        }
        Tok::RecSuffix => {
            if idx == 0 {
                (0..=s.len()).any(|k| match_toks(rest, idx + 1, &s[k..]))
            } else {
                !s.is_empty() && s[0] == '/' && (1..=s.len()).any(|k| match_toks(rest, idx + 1, &s[k..]))
            }
        }
        Tok::RecZeroOrMore => rec_zero_or_more(rest, idx, s),
        Tok::Alt(alts) => {
            for a in alts {
                let mut combined = a.clone();
                combined.extend_from_slice(rest);
                if match_toks(&combined, idx, s) {
                    return true;
                }
            }
            false
        }
    }
}

fn rec_zero_or_more(rest: &[Tok], idx: usize, s: &[char]) -> bool {
    // (?:/|/.*/)
    if s.is_empty() || s[0] != '/' {
        return false;
    }
    if match_toks(rest, idx + 1, &s[1..]) {
        return true;
    }
    for k in 1..s.len() {
        if s[k] == '/' && match_toks(rest, idx + 1, &s[k + 1..]) {
            return true;
        }
    }
    false
}

