            "error: the argument '{}' cannot be used multiple times\n\n{}\n\n{}",
            display(a),
            self.usage_generic(),
            self.err_footer()
        )
    }

    /// Validates a value; returns an error message on failure.
    fn validate(&self, idx: usize, v: &str) -> Result<(), String> {
        let a = &ARGS[idx];
        match a.id {
            "columns" => {
                if v.is_empty() {
                    return Err(format!(
                        "error: invalid value '' for '{}': cannot parse integer from empty string\n\n{}",
                        display(a),
                        self.err_footer()
                    ));
                }
                let digits = v.strip_prefix('+').unwrap_or(v);
                if digits.is_empty() || !digits.bytes().all(|b| b.is_ascii_digit()) {
                    return Err(format!(
                        "error: invalid value '{}' for '{}': invalid digit found in string\n\n{}",
                        v,
                        display(a),
                        self.err_footer()
                    ));
                }
                if digits.parse::<u64>().is_err() {
                    return Err(format!(
                        "error: invalid value '{}' for '{}': number too large to fit in target type\n\n{}",
                        v,
                        display(a),
                        self.err_footer()
                    ));
                }
                Ok(())
            }
            "output" => {
                if v == "json" {
                    Ok(())
                } else if v == "yaml" || v == "cbor" {
                    Err(format!(
                        "error: invalid value '{v}' for '{}': This version of tokei was compiled without any '{v}' serialization support, to enable serialization, reinstall tokei with the features flag.\n\n    cargo install tokei --features {v}\n\nIf you want to enable all supported serialization formats, you can use the 'all' feature.\n\n    cargo install tokei --features all\n\n\n{}",
                        display(a),
                        self.err_footer()
                    ))
                } else {
                    Err(format!(
                        "error: invalid value '{}' for '{}': \"{}\" is not a supported serialization format\n\n{}",
                        v,
                        display(a),
                        v,
                        self.err_footer()
                    ))
                }
            }
            _ if !a.possible.is_empty() => {
                let ignore_case = a.id != "num_format_style";
                let ok = a.possible.iter().any(|p| {
                    if ignore_case {
                        p.eq_ignore_ascii_case(v)
                    } else {
                        *p == v
                    }
                });
                if ok {
                    return Ok(());
                }
                if v.is_empty() {
                    return Err(self.missing_value(a));
                }
                let mut s = format!("error: invalid value '{}' for '{}'\n", v, display(a));
                let _ = writeln!(s, "  [possible values: {}]", a.possible.join(", "));
                s.push('\n');
                if let Some(sug) = did_you_mean(v, a.possible.iter().copied()) {
                    let _ = write!(s, "  tip: a similar value exists: '{}'\n\n", sug);
                }
                s.push_str(self.err_footer());
                Err(s)
            }
            _ => Ok(()),
        }
    }

    fn insert(&mut self, i: usize) {
        if self.counts[i] == 0 {
            self.seen.push(i);
        }
        self.counts[i] += 1;
    }

    fn resolve(&mut self, p: &mut Pending) -> Result<(), String> {
        match std::mem::replace(p, Pending::None) {
            Pending::None => Ok(()),
            Pending::Wanting(i) => Err(self.missing_value(&ARGS[i])),
            Pending::Have(i, v) => {
                if self.counts[i] > 0 && !ARGS[i].multiple {
                    return Err(self.duplicate(&ARGS[i]));
                }
                self.insert(i);
                self.validate(i, &v)?;
                self.values[i].push(v);
                Ok(())
            }
        }
    }

    fn flag(&mut self, i: usize) -> Result<(), String> {
        if self.counts[i] > 0 && !ARGS[i].multiple {
            return Err(self.duplicate(&ARGS[i]));
        }
        self.insert(i);
        Ok(())
    }
}

pub fn parse(args: &[String]) -> Outcome {
    let bin = args
        .first()
        .map(|a| {
            std::path::Path::new(a)
                .file_name()
                .map(|f| f.to_string_lossy().to_string())
                .unwrap_or_else(|| a.clone())
        })
        .unwrap_or_else(|| "tokei".to_string());
    let mut p = Parser {
        bin,
        seen: Vec::new(),
        counts: vec![0; ARGS.len()],
        values: vec![Vec::new(); ARGS.len()],
        input: Vec::new(),
    };
    let mut pending = Pending::None;
    let mut trailing = false;
    let mut idx = 1;
    macro_rules! tryo {
        ($e:expr) => {
            match $e {
                Ok(v) => v,
                Err(e) => return Outcome::Error(e),
            }
        };
    }
    while idx < args.len() {
        let tok = args[idx].clone();
        idx += 1;
        if trailing {
            p.input.push(tok);
            continue;
        }
        if tok == "--" {
            tryo!(p.resolve(&mut pending));
            trailing = true;
            continue;
        }
        if let Some(rest) = tok.strip_prefix("--") {
            let (name, val) = match rest.find('=') {
                Some(i) => (&rest[..i], Some(rest[i + 1..].to_string())),
                None => (rest, None),
            };
            let ai = match ARGS.iter().position(|a| a.long == name) {
                Some(i) => i,
                None => {
                    let _ = p.resolve(&mut pending);
                    let sug = did_you_mean(name, ARGS.iter().map(|a| a.long));
                    let sug = sug.and_then(|s| ARGS.iter().position(|a| a.long == s));
                    return Outcome::Error(p.unexpected_long(&format!("--{}", name), sug));
                }
            };
            let a = &ARGS[ai];
            match a.kind {
                Kind::Flag | Kind::Count => {
                    if let Some(v) = val {
                        let mut used: Vec<usize> = p.seen.clone();
                        if !used.contains(&ai) {
                            used.push(ai);
                        }
                        return Outcome::Error(format!(
                            "error: unexpected value '{}' for '{}' found; no more were expected\n\n{}\n\n{}",
                            v,
                            display(a),
                            p.usage_from(&used, false),
                            p.err_footer()
                        ));
                    }
                    tryo!(p.resolve(&mut pending));
                    tryo!(p.flag(ai));
                    if a.id == "help" {
                        return Outcome::Help;
                    }
                    if a.id == "version" {
                        return Outcome::Version;
                    }
                }
                Kind::Opt => {
                    tryo!(p.resolve(&mut pending));
                    match val {
                        Some(v) => pending = Pending::Have(ai, v),
                        None => pending = Pending::Wanting(ai),
                    }
                }
            }
            continue;
        }
        if tok.starts_with('-') && tok.len() > 1 {
            // short flags
            let chars: Vec<char> = tok[1..].chars().collect();
            let mut ci = 0;
            while ci < chars.len() {
                let c = chars[ci];
                let ai = match ARGS.iter().position(|a| a.short == Some(c)) {
                    Some(i) => i,
                    None => {
                        let _ = p.resolve(&mut pending);
                        return Outcome::Error(p.unexpected_short(&format!("-{}", c)));
                    }
                };
                tryo!(p.resolve(&mut pending));
                let a = &ARGS[ai];
                match a.kind {
                    Kind::Flag | Kind::Count => {
                        tryo!(p.flag(ai));
                        if a.id == "help" {
                            return Outcome::Help;
                        }
                        if a.id == "version" {
                            return Outcome::Version;
                        }
                        ci += 1;
                    }
                    Kind::Opt => {
                        let rest: String = chars[ci + 1..].iter().collect();
                        if rest.is_empty() {
                            pending = Pending::Wanting(ai);
                        } else {
                            let v = rest.strip_prefix('=').unwrap_or(&rest).to_string();
                            pending = Pending::Have(ai, v);
                        }
                        break;
                    }
                }
            }
            continue;
        }
        // a value
        match pending {
            Pending::Wanting(i) => {
                pending = Pending::Have(i, tok);
            }
            _ => {
                tryo!(p.resolve(&mut pending));
                p.input.push(tok);
            }
        }
    }
    tryo!(p.resolve(&mut pending));

    // Conflicts
    let conflicts: &[(&str, &str)] = &[
        ("output", "num_format_style"),
        ("num_format_style", "output"),
        ("sort", "rsort"),
        ("rsort", "sort"),
    ];
    for &i in &p.seen {
        let a = &ARGS[i];
        for (x, y) in conflicts {
            if a.id == *x {
                if let Some(j) = ARGS.iter().position(|b| b.id == *y) {
                    if p.counts[j] > 0 {
                        let used: Vec<usize> = p.seen.iter().copied().filter(|&k| k != j).collect();
                        return Outcome::Error(format!(
                            "error: the argument '{}' cannot be used with '{}'\n\n{}\n\n{}",
                            display(a),
                            display(&ARGS[j]),
                            p.usage_from(&used, !p.input.is_empty()),
                            p.err_footer()
                        ));
                    }
                }
            }
        }
    }

    let get = |id: &str| -> &Vec<String> {
        let i = ARGS.iter().position(|a| a.id == id).unwrap();
        &p.values[i]
    };
    let cnt = |id: &str| -> usize {
        let i = ARGS.iter().position(|a| a.id == id).unwrap();
        p.counts[i]
    };
    let mut cli = Cli::default();
    cli.columns = get("columns").first().map(|v| v.strip_prefix('+').unwrap_or(v).parse().unwrap_or(0));
    cli.excluded = get("exclude").clone();
    cli.files = cnt("files") > 0;
    cli.file_input = get("file_input").first().cloned();
    cli.hidden = cnt("hidden") > 0;
    cli.languages = cnt("languages") > 0;
    cli.no_ignore = cnt("no_ignore") > 0;
    cli.no_ignore_parent = cnt("no_ignore_parent") > 0;
    cli.no_ignore_dot = cnt("no_ignore_dot") > 0;
    cli.no_ignore_vcs = cnt("no_ignore_vcs") > 0;
    cli.output = get("output").first().cloned();
    cli.streaming = get("streaming").first().map(|v| {
        if v.eq_ignore_ascii_case("json") {
            Streaming::Json
        } else {
            Streaming::Simple
        }
    });
    cli.sort = get("sort").first().and_then(|v| Sort::from_str_ci(v));
    cli.rsort = get("rsort").first().and_then(|v| Sort::from_str_ci(v));
    let types = get("types");
    if !types.is_empty() {
        let mut t = Vec::new();
        for v in types {
            for x in v.split(',') {
                t.push(x.to_string());
            }
        }
        cli.types = Some(t);
    }
    cli.compact = cnt("compact") > 0;
    cli.num_format = get("num_format_style").first().map(|v| match v.as_str() {
        "commas" => NumFormat::Commas,
        "dots" => NumFormat::Dots,
        "underscores" => NumFormat::Underscores,
        _ => NumFormat::Plain,
    });
    cli.verbose = cnt("verbose") as u64;
    cli.input = p.input.clone();
    Outcome::Run(cli)
}

