pub fn print_languages_list(w: &mut dyn Write, color: bool, term_cols: Option<usize>) -> std::io::Result<()> {
    let b = |s: &str| -> String {
        if color {
            format!("\\x1b[1m{}\\x1b[0m", s)
        } else {
            s.to_string()
        }
    };
