        b(&pad_right(&truncate_dots("    Extensions", ew), ew)),
        b("┃")
    )?;
    writeln!(w, "{}{}{}{}", b("┃"), b(&"━".repeat(lw)), b(&"━".repeat(ew)), b("┃"))?;
    let name_w = lw + 3;
    let ext_w = ew.saturating_sub(5);
    for i in 0..lang::count() {
        let d = lang::def(i);
        let exts = if d.extensions.is_empty() {
            "<None>".to_string()
        } else {
            d.extensions.join(", ")
        };
        let exts = truncate_dots(&exts, ext_w);
        let name = truncate_dots(d.name, lw.saturating_sub(2));
        writeln!(
            w,
            "{} {}{} {}",
            b("┃"),
            pad_right(&name, name_w),
            pad_right(&exts, ext_w),
            b("┃")
        )?;
    }
    writeln!(w, "{}", b(&row))?;
    writeln!(w)
}

