/// with a single call.
pub struct LineBuf<W: Write> {
    inner: W,
    buf: Vec<u8>,
}

impl<W: Write> LineBuf<W> {
    pub fn new(inner: W) -> Self {
        LineBuf { inner, buf: Vec::with_capacity(8192) }
    }
    pub fn line(&mut self, s: &str) -> std::io::Result<()> {
        let n = s.len() + 1;
        if self.buf.len() + n > 8192 {
            self.inner.write_all(&self.buf)?;
            self.buf.clear();
        }
        if n >= 8192 {
            self.inner.write_all(s.as_bytes())?;
            self.inner.write_all(b"\\n")?;
        } else {
            self.buf.extend_from_slice(s.as_bytes());
            self.buf.push(b'\\n');
        }
        Ok(())
    }
    pub fn flush(&mut self) -> std::io::Result<()> {
        self.inner.write_all(&self.buf)?;
        self.buf.clear();
        self.inner.flush()
    }
    /// Drops buffered (unflushed) data, flushing only what was already written.
    pub fn abandon(&mut self) {
        self.buf.clear();
        let _ = self.inner.flush();
    }
}

